def x_kol_rss_template_candidates(
    handle: str,
    templates: list[str],
    *,
    limit: int,
) -> list[str]:
    now = time.time()
    with X_KOL_RSS_PREFERENCE_LOCK:
        preferred = X_KOL_RSS_PREFERRED_TEMPLATES.get(handle.lower(), "")
    with X_KOL_RSS_MIRROR_HEALTH_LOCK:
        health = {template: dict(X_KOL_RSS_MIRROR_HEALTH.get(template) or {}) for template in templates}
    ready = [template for template in templates if safe_float(health[template].get("retryAt"), 0) <= now]
    if not ready and templates:
        # Half-open the mirror whose cooldown ends first. Otherwise a brief
        # fleet-wide outage leaves every account red until all timers expire.
        ready = [min(
            templates,
            key=lambda template: (
                safe_float(health[template].get("retryAt"), 0),
                int(safe_float(health[template].get("failures"), 0)),
                templates.index(template),
            ),
        )]
    ready.sort(key=lambda template: (
        0 if template == preferred else 1,
        int(safe_float(health[template].get("failures"), 0)),
        -safe_float(health[template].get("lastOkAt"), 0),
        templates.index(template),
    ))
    return ready[: max(1, limit)]


def x_kol_record_rss_mirror_result(result: dict[str, Any]) -> None:
    template = str(result.get("template") or "")
    if not template:
        return
    now = time.time()
    with X_KOL_RSS_MIRROR_HEALTH_LOCK:
        previous = dict(X_KOL_RSS_MIRROR_HEALTH.get(template) or {})
        if result.get("ok"):
            X_KOL_RSS_MIRROR_HEALTH[template] = {
                "failures": 0,
                "retryAt": 0,
                "lastOkAt": now,
                "latencySeconds": round(safe_float(result.get("elapsed"), 0), 3),
            }
            return
        failures = min(8, int(safe_float(previous.get("failures"), 0)) + 1)
        cooldown = min(
            X_KOL_RSS_CIRCUIT_MAX_SECONDS,
            X_KOL_RSS_CIRCUIT_BASE_SECONDS * (2 ** (failures - 1)),
        )
        X_KOL_RSS_MIRROR_HEALTH[template] = {
            **previous,
            "failures": failures,
            "retryAt": now + cooldown,
            "lastErrorAt": now,
            "latencySeconds": round(safe_float(result.get("elapsed"), 0), 3),
        }


def normalize_x_keywords(value: Any) -> list[str]:
    if isinstance(value, list):
        raw_parts = value
    else:
        raw_parts = re.split(r"[,，\s]+", str(value or ""))
    keywords = []
    seen = set()
    for part in raw_parts:
        word = clean_feed_text(part, 40).lower()
        if not word or word in seen:
            continue
        seen.add(word)
        keywords.append(word)
    return keywords[:16]


def x_kol_item_matches(source: dict[str, Any], text: str) -> bool:
    if not x_kol_strict_keywords():
        return True
    keywords = normalize_x_keywords(source.get("keywords"))
    if not keywords:
        return True
    haystack = text.lower()
    return any(word in haystack for word in keywords)


def x_kol_keyword_hits(source: dict[str, Any], text: str) -> list[str]:
    keywords = normalize_x_keywords(source.get("keywords"))
    if not keywords:
        return []
    haystack = text.lower()
    return [word for word in keywords if word in haystack]


X_KOL_CATEGORIES: tuple[tuple[str, str], ...] = (
    ("kol", "普通KOL"),
    ("celebrity", "明星"),
    ("notable", "名人"),
    ("founder", "项目创始人/联合创始人"),
    ("project_official", "项目官方X"),
)
X_KOL_CATEGORY_IDS = {category_id for category_id, _label in X_KOL_CATEGORIES}
X_NEWS_TRADE_CATEGORY_IDS = frozenset({"celebrity", "notable", "founder", "project_official"})
X_KOL_CATEGORY_ALIASES = {
    "kol": "kol",
    "普通kol": "kol",
    "普通kols": "kol",
    "普通": "kol",
    "celebrity": "celebrity",
    "明星": "celebrity",
    "notable": "notable",
    "名人": "notable",
    "founder": "founder",
    "cofounder": "founder",
    "co-founder": "founder",
    "项目创始人": "founder",
    "项目联合创始人": "founder",
    "项目创始人/联合创始人": "founder",
    "project_official": "project_official",
    "official": "project_official",
    "项目官方": "project_official",
    "项目官方x": "project_official",
}
X_KOL_KNOWN_PROJECT_OFFICIAL_HANDLES = {
    "longdotxyz", "pinkbrains_io", "ponsdotfamily", "robinhoodapp", "robinhoodcrypto",
}
X_KOL_KNOWN_FOUNDER_HANDLES = {
    "justinsuntron", "natan_benish", "sunyuchentron", "vladtenev",
}
X_KOL_KNOWN_NOTABLE_HANDLES = {"elonmusk"}


def normalize_x_kol_category(
    value: Any,
    *,
    handle: str = "",
    display_name: str = "",
    keywords: Any = None,
) -> str:
    raw = clean_feed_text(value, 48).lower().replace(" ", "")
    if raw in X_KOL_CATEGORY_ALIASES:
        return X_KOL_CATEGORY_ALIASES[raw]
    if raw in X_KOL_CATEGORY_IDS:
        return raw

    normalized_handle = normalize_x_handle(handle).lower()
    keyword_text = " ".join(normalize_x_keywords(keywords)).lower()
    identity_text = f"{display_name} {keyword_text}".lower()
    if normalized_handle in X_KOL_KNOWN_PROJECT_OFFICIAL_HANDLES or any(
        marker in identity_text for marker in ("官方账号", "项目官方", "官方x", "官方推特")
    ):
        return "project_official"
    if normalized_handle in X_KOL_KNOWN_FOUNDER_HANDLES or any(
        marker in identity_text
        for marker in ("联合创始人", "创始人", "联创人", "联创", "co-founder", "cofounder", "founder")
    ):
        return "founder"
    if normalized_handle in X_KOL_KNOWN_NOTABLE_HANDLES:
        return "notable"
    return "kol"


def x_kol_category_label(value: Any) -> str:
    category = clean_feed_text(value, 48)
    return dict(X_KOL_CATEGORIES).get(category, dict(X_KOL_CATEGORIES)["kol"])


def normalize_x_source(value: Any) -> dict[str, Any] | None:
    if not isinstance(value, dict):
        return None
    handle = normalize_x_handle(value.get("handle") or value.get("username") or value.get("url"))
    if not handle:
        return None
    display_name = clean_feed_text(value.get("displayName") or value.get("name") or handle, 80)
    keywords = normalize_x_keywords(value.get("keywords"))
    source = {
        "id": x_kol_source_id(handle),
        "handle": handle,
        "displayName": display_name or handle,
        "category": normalize_x_kol_category(
            value.get("category") or value.get("categoryId") or value.get("categoryType"),
            handle=handle,
            display_name=display_name,
            keywords=keywords,
        ),
        "keywords": keywords,
        "enabled": value.get("enabled") is not False,
        "createdAt": int(safe_float(value.get("createdAt")) or time.time() * 1000),
    }
    avatar = x_kol_avatar_url(handle, value.get("avatar") or value.get("avatarUrl"))
    if avatar:
        source["avatar"] = avatar
    return source


def merge_x_kol_manual_source_payloads(*payloads: Any) -> list[dict[str, Any]]:
    """Merge legacy/manual stores by handle while letting newer stores win."""
    merged: dict[str, dict[str, Any]] = {}
    for payload in payloads:
        raw_sources = payload.get("sources") if isinstance(payload, dict) else []
        if not isinstance(raw_sources, list):
            continue
        for raw in raw_sources:
            source = normalize_x_source(raw)
            if source:
                merged[source["id"]] = source
    return list(merged.values())[:80]


def load_x_kol_sources(user: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    target_user = user or admin_user()
    if target_user:
        migrate_x_kol_sources_to_db(target_user)
        database_payload = load_user_payload(target_user, USER_SCOPE_X_KOL_SOURCES)
        legacy_payloads: list[dict[str, Any]] = []
        if target_user.get("role") == "admin" and X_KOL_SOURCES_PATH.exists():
            legacy_payloads.append(read_json_cache(X_KOL_SOURCES_PATH))
        user_path = x_kol_sources_path(target_user)
        if user_path.exists():
            legacy_payloads.append(read_json_cache(user_path))
        sources = merge_x_kol_manual_source_payloads(*legacy_payloads, database_payload)
        database_sources = merge_x_kol_manual_source_payloads(database_payload)
        # Older builds wrote either the global JSON file, a user JSON file, or
        # the database. Reconcile them once without allowing a stale copy to
        # overwrite a newer record for the same handle.
        if sources != database_sources:
            healed = {"sources": sources, "updatedAt": int(time.time() * 1000)}
            save_user_payload(target_user, USER_SCOPE_X_KOL_SOURCES, healed)
            write_json_cache(user_path, healed)
            if target_user.get("role") == "admin":
                write_json_cache(X_KOL_SOURCES_PATH, healed)
        return sources
    return merge_x_kol_manual_source_payloads(read_json_cache(X_KOL_SOURCES_PATH))


def x_kol_priority_handles() -> tuple[str, ...]:
    raw = os.getenv("X_KOL_PRIORITY_HANDLES", "whitestar224")
    handles: list[str] = []
    seen: set[str] = set()
    for value in str(raw or "").split(","):
        handle = normalize_x_handle(value).lower()
        if handle and handle not in seen:
            seen.add(handle)
            handles.append(handle)
    return tuple(handles or ["whitestar224"])


def x_kol_personal_api_handle() -> str:
    """Paid X access is pinned to the single explicitly approved owner account."""
    return X_OFFICIAL_API_APPROVED_PERSONAL_HANDLE


def x_kol_official_paid_source_allowed(source: dict[str, Any]) -> bool:
    return normalize_x_handle(source.get("handle")).lower() == x_kol_personal_api_handle()


def x_kol_priority_rss_interval_seconds() -> float:
    return max(0.75, safe_float(os.getenv("X_KOL_PRIORITY_RSS_INTERVAL_SECONDS"), 1.0))


def x_kol_priority_api_interval_seconds() -> float:
    return max(5.0, safe_float(os.getenv("X_KOL_PRIORITY_API_INTERVAL_SECONDS"), 15.0))


def x_kol_priority_rss_timeout_seconds() -> float:
    # Public mirrors are only a recovery path. The currently reliable mirror often
    # needs 4-5 seconds, so a two-second cutoff made this account appear offline.
    return max(1.0, safe_float(os.getenv("X_KOL_PRIORITY_RSS_TIMEOUT_SECONDS"), 6.0))


def x_kol_priority_rss_mirrors() -> int:
    return max(1, min(4, int(safe_float(os.getenv("X_KOL_PRIORITY_RSS_MIRRORS"), 3))))


def x_kol_priority_sources() -> list[dict[str, Any]]:
    saved = {
        normalize_x_handle(source.get("handle")).lower(): source
        for source in load_x_kol_sources(None)
        if normalize_x_handle(source.get("handle"))
    }
    sources: list[dict[str, Any]] = []
    for handle in x_kol_priority_handles():
        source = saved.get(handle)
        if source:
            sources.append({**source, "enabled": True, "keywords": [], "priority": True})
            continue
        fallback = normalize_x_source(
            {
                "id": f"x-priority-{handle}",
                "handle": handle,
                "displayName": "\u767d\u661f" if handle == "whitestar224" else handle,
                "enabled": True,
            }
        )
        if fallback:
            sources.append({**fallback, "priority": True})
    return sources


def personal_x_monitor_payload(payload: dict[str, Any] | None) -> dict[str, Any]:
    """Expose only the configured owner account from the existing priority realtime feed."""
    source_payload = payload if isinstance(payload, dict) else {}
    handle = x_kol_priority_handles()[0].lower()
    sources = [
        dict(row)
        for row in source_payload.get("sources") or []
        if isinstance(row, dict) and normalize_x_handle(row.get("handle")).lower() == handle
    ]
    account = sources[0] if sources else next(
        (
            dict(row)
            for row in x_kol_priority_sources()
            if normalize_x_handle(row.get("handle")).lower() == handle
        ),
        {"id": f"x:{handle}", "handle": handle, "displayName": handle},
    )
    source_ids = {str(row.get("id") or "") for row in sources} | {str(account.get("id") or "")}
    items = [
        dict(row)
        for row in source_payload.get("items") or []
        if isinstance(row, dict)
        and (
            normalize_x_handle(row.get("handle")).lower() == handle
            or str(row.get("sourceId") or "") in source_ids
        )
    ][:120]
    last_published_at = max((int(safe_float(row.get("publishedAt")) or 0) for row in items), default=0)
    transport = str(source_payload.get("upstreamMode") or source_payload.get("provider") or "")
    tactical_signals = strategy_tactical_signal_rows()
    public_account = {
        "id": account.get("id") or f"x:{handle}",
        "handle": handle,
        "displayName": account.get("displayName") or account.get("name") or handle,
        "avatar": account.get("avatar") or x_kol_avatar_url(handle),
        "status": account.get("status") or ("connecting" if source_payload.get("pending") else "ok"),
        "provider": account.get("provider") or source_payload.get("provider") or "",
    }
    return {
        "ok": not bool(source_payload.get("error")),
        "pending": bool(source_payload.get("pending")),
        "realtime": bool(source_payload.get("realtime")),
        "transport": source_payload.get("transport") or ("sse" if source_payload.get("realtime") else "snapshot"),
        "upstreamMode": transport,
        "historyRestored": bool(source_payload.get("historyRestored")),
        "cached": bool(source_payload.get("cached")),
        "stale": bool(source_payload.get("stale")),
        "account": public_account,
        "sources": sources or [public_account],
        "items": items,
        "officialApiCostGuard": source_payload.get("officialApiCostGuard") or x_kol_api_cost_snapshot(),
        "tacticalSignals": tactical_signals,
        "tacticalSignalTypes": [
            {"key": "watch", "label": "重点看"},
            {"key": "main-wave-expected", "label": "有主升浪预期"},
        ],
        "summary": {
            "posts": len(items),
            "lastPublishedAt": last_published_at,
            "transport": transport,
            "connected": bool(source_payload.get("realtime") and not source_payload.get("pending")),
            "historyRestored": bool(source_payload.get("historyRestored")),
            "tacticalSignals": len(tactical_signals),
        },
        "message": source_payload.get("message") or "",
        "error": source_payload.get("error") or "",
        "updatedAt": int(safe_float(source_payload.get("updatedAt")) or time.time() * 1000),
    }


def feedback_json_value(value: Any, depth: int = 0) -> Any:
    if depth > 6:
        return None
    if value is None or isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        number = float(value)
        return value if math.isfinite(number) else 0
    if isinstance(value, str):
        return value[:1200]
    if isinstance(value, list):
        return [feedback_json_value(item, depth + 1) for item in value[:32]]
    if isinstance(value, dict):
        return {
            str(key)[:80]: feedback_json_value(item, depth + 1)
            for key, item in list(value.items())[:64]
        }
    return str(value)[:1200]


def normalize_dragon_wave_feedback(value: Any) -> dict[str, Any]:
    payload = value if isinstance(value, dict) else {}
    raw_records = payload.get("records") if isinstance(payload.get("records"), dict) else {}
    ordered = sorted(
        raw_records.items(),
        key=lambda item: int(safe_float((item[1] or {}).get("updatedAt"), 0)) if isinstance(item[1], dict) else 0,
        reverse=True,
    )[:1200]
    records: dict[str, dict[str, Any]] = {}
    for raw_key, raw_record in ordered:
        if not isinstance(raw_record, dict):
            continue
        key = str(raw_key or raw_record.get("key") or "")[:240]
        decision = str(raw_record.get("decision") or "")
        if not key or decision not in {"confirmed", "pending", "denied", "cleared"}:
            continue
        signal = feedback_json_value(raw_record.get("signal") if isinstance(raw_record.get("signal"), dict) else {})
        signal = signal if isinstance(signal, dict) else {}
        certainty_grade = "" if decision == "cleared" else str(raw_record.get("certaintyGrade") or signal.get("manualCertaintyGrade") or "").upper().strip()
        if certainty_grade not in {"A+", "A", "B"}:
            certainty_grade = ""
        if certainty_grade:
            signal["manualCertaintyGrade"] = certainty_grade
        else:
            signal.pop("manualCertaintyGrade", None)
        allowed_structure_tags = {
            "horizontalLaunch", "trendlineBreakout", "triangle", "box",
            "fallingWedge", "pivot", "previousHighBreakout", "consolidationBreakout", "ema90Pullback",
            "volumeBreakout", "nearPreviousHighConsolidation", "newCoinNotFalling",
        }
        raw_structure_tags = raw_record.get("structureTags")
        if not isinstance(raw_structure_tags, list):
            raw_structure_tags = signal.get("manualStructureTags") if isinstance(signal.get("manualStructureTags"), list) else []
        structure_tags = [] if decision == "cleared" else list(dict.fromkeys(str(item) for item in raw_structure_tags if str(item) in allowed_structure_tags))
        if structure_tags:
            signal["manualStructureTags"] = structure_tags
        else:
            signal.pop("manualStructureTags", None)
        raw_predicted_tags = raw_record.get("predictedStructureTags")
        if not isinstance(raw_predicted_tags, list):
            raw_predicted_tags = signal.get("predictedStructureTags") if isinstance(signal.get("predictedStructureTags"), list) else None
        predicted_tags = None if raw_predicted_tags is None else ([] if decision == "cleared" else list(dict.fromkeys(str(item) for item in raw_predicted_tags if str(item) in allowed_structure_tags)))
        structure_review = None
        if predicted_tags is not None and decision != "cleared":
            matched = sorted(tag for tag in predicted_tags if tag in structure_tags)
            added = sorted(tag for tag in structure_tags if tag not in predicted_tags)
            removed = sorted(tag for tag in predicted_tags if tag not in structure_tags)
            union_size = len(set(predicted_tags + structure_tags))
            structure_review = {
                "predicted": sorted(predicted_tags), "reviewed": sorted(structure_tags), "matched": matched,
                "addedByUser": added, "removedByUser": removed,
                "agreement": round(len(matched) / union_size, 3) if union_size else 1,
                "exact": not added and not removed,
            }
            signal["predictedStructureTags"] = predicted_tags
            signal["structureReview"] = structure_review
        else:
            signal.pop("predictedStructureTags", None)
            signal.pop("structureReview", None)
        records[key] = {
            "key": key,
            "decision": decision,
            "optimizationLabel": 1 if decision == "confirmed" else -1 if decision == "denied" else 0,
            "optimizationRole": "positive" if decision == "confirmed" else "negative" if decision == "denied" else "unlabeled" if decision == "pending" else "deleted",
            "datasetVersion": 10,
            "createdAt": max(0, int(safe_float(raw_record.get("createdAt"), 0))),
            "updatedAt": max(0, int(safe_float(raw_record.get("updatedAt"), 0))),
            "pair": str(raw_record.get("pair") or "")[:32],
            "interval": str(raw_record.get("interval") or "")[:8],
            "venue": str(raw_record.get("venue") or "")[:80],
            "certaintyGrade": certainty_grade,
            "structureTags": structure_tags,
            **({"predictedStructureTags": predicted_tags, "structureReview": structure_review} if predicted_tags is not None else {}),
            "signal": signal,
        }
    updated_at = max([int(item.get("updatedAt") or 0) for item in records.values()] or [0])
    return {"version": 1, "updatedAt": updated_at, "records": records}


def dragon_wave_feedback_feature_tokens(signal: Any) -> list[str]:
    signal = signal if isinstance(signal, dict) else {}
    foundations = sorted({str(item) for item in signal.get("foundationTypes", [])}) if isinstance(signal.get("foundationTypes"), list) else []
    auxiliaries = sorted({str(item) for item in signal.get("auxiliaryTypes", [])}) if isinstance(signal.get("auxiliaryTypes"), list) else []
    confluence = sorted({str(item) for item in signal.get("confluence", [])}) if isinstance(signal.get("confluence"), list) else []
    interval = str(signal.get("interval") or "").strip()
    structure_shape = str(signal.get("structureShape") or "none").strip() or "none"
    tokens = [f"foundation:{item}" for item in foundations]
    tokens.extend(f"auxiliary:{item}" for item in auxiliaries)
    if signal.get("patternKey"):
        tokens.append(f"pattern:{signal['patternKey']}")
    if confluence:
        tokens.append(f"combo:{'+'.join(confluence)}")
    if interval:
        tokens.append(f"interval:{interval}")
        if foundations and "manualReview" not in foundations:
            tokens.append(f"interval-foundation:{interval}|{'+'.join(foundations)}")
            tokens.append(f"interval-auxiliary:{interval}|{'+'.join(auxiliaries) or 'none'}")
            tokens.append(f"interval-shape:{interval}|{structure_shape}")
            tokens.append(f"interval-setup:{interval}|{'+'.join(foundations)}>{'+'.join(auxiliaries) or 'none'}|{structure_shape}")
    context_tokens = sorted({str(item) for item in signal.get("contextTokens", [])}) if isinstance(signal.get("contextTokens"), list) else []
    tokens.extend(f"context:{item}" for item in context_tokens)
    allowed_structure_tags = {
        "horizontalLaunch", "trendlineBreakout", "triangle", "box",
        "fallingWedge", "pivot", "previousHighBreakout", "consolidationBreakout", "ema90Pullback",
        "volumeBreakout", "nearPreviousHighConsolidation", "newCoinNotFalling",
    }
    structure_tags = sorted({str(item) for item in signal.get("manualStructureTags", []) if str(item) in allowed_structure_tags}) if isinstance(signal.get("manualStructureTags"), list) else []
    tokens.extend(f"manual-structure:{item}" for item in structure_tags)
    predicted_tags = sorted({str(item) for item in signal.get("predictedStructureTags", []) if str(item) in allowed_structure_tags}) if isinstance(signal.get("predictedStructureTags"), list) else []
    tokens.extend(f"strategy-structure:{item}" for item in predicted_tags)
    review = signal.get("structureReview") if isinstance(signal.get("structureReview"), dict) else None
    if review:
        for field, prefix in (("matched", "review-match"), ("addedByUser", "review-added"), ("removedByUser", "review-removed")):
            values = sorted({str(item) for item in review.get(field, []) if str(item) in allowed_structure_tags}) if isinstance(review.get(field), list) else []
            tokens.extend(f"{prefix}:{item}" for item in values)
        agreement = safe_float(review.get("agreement"), 0)
        tokens.append(f"review-agreement:{'exact' if review.get('exact') else 'partial' if agreement >= 0.5 else 'low'}")
    def metric_band(name: str, field: str, boundaries: tuple[float, ...], labels: tuple[str, ...]) -> None:
        raw_value = signal.get(field)
        if raw_value is None or isinstance(raw_value, bool):
            return
        number = safe_float(raw_value, float("nan"))
        if not math.isfinite(number):
            return
        index = next((cursor for cursor, boundary in enumerate(boundaries) if number < boundary), len(labels) - 1)
        tokens.append(f"quality:{name}:{labels[index]}")
    metric_band("base-bars", "consolidationBars", (20, 40, 80), ("short", "forming", "mature", "long"))
    metric_band("outer-edge", "outerEdgeScore", (60, 80), ("weak", "clean", "strong"))
    metric_band("ceiling-touches", "ceilingTouches", (2, 3), ("single", "double", "multiple"))
    metric_band("rhythm", "rhythmScore", (60, 75), ("weak", "flowing", "elite"))
    metric_band("certainty", "certaintyScore", (70, 85), ("low", "high", "elite"))
    metric_band("order-flow", "orderFlowScore", (60, 75), ("quiet", "supportive", "strong"))
    metric_band("launch-distance", "launchDistancePercent", (2, 7), ("attached", "near", "far"))
    metric_band("prior-range", "priorRangePercent", (4, 8), ("tight", "controlled", "wide"))
    metric_band("prior-drift", "priorDriftPercent", (2, 6), ("flat", "controlled", "trending"))
    metric_band("prior-volume", "priorVolumeRatio", (1, 1.35), ("dry", "normal", "expanding"))
    metric_band("channel-occupancy", "channelInteriorOccupancy", (0.5, 0.7), ("hollow", "occupied", "full"))
    metric_band("channel-hollow", "channelHollowRatio", (0.25, 0.42), ("low", "moderate", "high"))
    metric_band("channel-transitions", "channelSideTransitions", (2, 5), ("single-side", "rotating", "active"))
    if signal.get("outerEdgeConfirmed") is True:
        tokens.append("quality:outer-edge-confirmed")
    if signal.get("aboveEma90") is True:
        tokens.append("quality:above-ema90")
    if signal.get("breaksPriorHigh") is True:
        tokens.append("quality:breaks-prior-high")
    grade = str(signal.get("manualCertaintyGrade") or "").upper().strip()
    if grade in {"A+", "A", "B"}:
        tokens.append(f"manual-grade:{grade}")
    return list(dict.fromkeys(tokens))


DRAGON_WAVE_FEEDBACK_INDEX_SIGNAL_FIELDS = (
    "time", "interval", "pattern", "patternKey", "price", "triggerPrice", "level",
    "selectedPrice", "status", "score", "certaintyScore", "relativeVolume",
    "structureShape", "manualCandleSelection", "manualSource",
    "open", "high", "low", "close", "volume",
)


def dragon_wave_feedback_display_index(value: Any) -> dict[str, Any]:
    normalized = normalize_dragon_wave_feedback(value)
    records: dict[str, Any] = {}
    for key, record in normalized["records"].items():
        signal = record.get("signal") if isinstance(record.get("signal"), dict) else {}
        compact_signal = {
            field: signal[field]
            for field in DRAGON_WAVE_FEEDBACK_INDEX_SIGNAL_FIELDS
            if field in signal
        }
        compact_signal["feedbackTokens"] = dragon_wave_feedback_feature_tokens({
            **signal,
            "interval": record.get("interval") or signal.get("interval"),
        })[:32]
        records[key] = {
            field: record.get(field)
            for field in (
                "key", "decision", "createdAt", "updatedAt", "pair", "interval", "venue",
                "certaintyGrade", "structureTags", "predictedStructureTags",
            )
            if field in record
        }
        records[key]["signal"] = compact_signal
    return {
        "version": 1,
        "updatedAt": normalized.get("updatedAt", 0),
        "records": records,
    }


def dragon_wave_supervised_prototype_profile(rows: list[dict[str, Any]]) -> dict[str, Any]:
    def percentile(values: list[float], ratio: float) -> float:
        ordered = sorted(float(value) for value in values)
        if not ordered:
            return 0
        position = (len(ordered) - 1) * ratio
        lower = int(position)
        upper = min(len(ordered) - 1, lower + 1)
        return ordered[lower] + (ordered[upper] - ordered[lower]) * (position - lower)

    def build(selected: list[dict[str, Any]], sample_key: str) -> dict[str, Any]:
        groups: dict[str, dict[str, Any]] = {}
        for row in selected:
            tags = sorted(row.get("structureTags") or [])
            setup_token = next((token for token in row.get("featureTokens", []) if token.startswith("interval-setup:")), "")
            setup_signature = setup_token.split("|", 1)[1] if "|" in setup_token else "none>none|none"
            key = f"{row['interval']}|manual:{'+'.join(tags)}" if tags else f"{row['interval']}|setup:{setup_signature}"
            group = groups.setdefault(key, {
                "interval": row["interval"], "structureTags": tags, "setupSignature": setup_signature,
                "rows": [], "pairs": set(),
            })
            group["rows"].append(row)
            group["pairs"].add(row["pair"])
        prototypes: list[dict[str, Any]] = []
        for key, group in groups.items():
            metric_names = sorted({name for row in group["rows"] for name in row.get("metrics", {}) if name != "manualCertaintyLevel"})
            metrics = {}
            for name in metric_names:
                values = [row["metrics"][name] for row in group["rows"] if name in row.get("metrics", {})]
                metrics[name] = {"low": percentile(values, 0.25), "median": percentile(values, 0.5), "high": percentile(values, 0.75)}
            counts: dict[str, int] = {}
            for row in group["rows"]:
                for token in row.get("featureTokens", []):
                    if token.startswith(("quality:", "context:", "manual-structure:", "strategy-structure:", "review-")):
                        counts[token] = counts.get(token, 0) + 1
            prototypes.append({
                "key": key,
                "interval": group["interval"],
                "structureTags": group["structureTags"],
                "setupSignature": group["setupSignature"],
                "sampleCount": len(group["rows"]),
                "pairCount": len(group["pairs"]),
                "metrics": metrics,
                "sharedReasons": sorted((token for token, count in counts.items() if count / len(group["rows"]) >= 0.6), key=lambda token: (-counts[token], token)),
            })
        prototypes.sort(key=lambda item: (-item["sampleCount"], item["key"]))
        return {sample_key: sum(item["sampleCount"] for item in prototypes), "prototypes": prototypes}

    return {
        "positiveAPlus": build([row for row in rows if row["decision"] == "confirmed" and row["certaintyGrade"] == "A+"], "totalAPlusSamples"),
        "negativeDenied": build([row for row in rows if row["decision"] == "denied"], "totalDeniedSamples"),
        "policy": "causal-feature-combination-only",
    }


def dragon_wave_feedback_optimization(value: Any) -> dict[str, Any]:
    normalized = normalize_dragon_wave_feedback(value)
    metric_fields = (
        "score", "certaintyScore", "rhythmScore", "sentimentScore",
        "orderFlowScore", "consolidationBars", "relativeVolume", "structuralRiskPercent",
        "ceilingAge", "ceilingTouches", "outerEdgeScore",
        "platformTouchGroups", "launchDistancePercent", "compressionRatioAtDecision",
        "channelInteriorOccupancy", "channelMiddleParticipationRatio", "channelHollowRatio", "channelLongestHollowRun", "channelSideTransitions",
        "ema90AtDecision", "atrAtDecision", "priorHighAtDecision", "priorLowAtDecision",
        "priorRangePercent", "priorDriftPercent", "priorVolumeRatio", "selectedPrice",
    )
    rows: list[dict[str, Any]] = []
    for record in sorted(normalized["records"].values(), key=lambda item: (item["updatedAt"], item["key"])):
        if record["decision"] == "cleared":
            continue
        signal = record.get("signal") if isinstance(record.get("signal"), dict) else {}
        metrics = {}
        for field in metric_fields:
            raw_value = signal.get(field)
            if raw_value is None or isinstance(raw_value, bool):
                continue
            number = safe_float(raw_value, float("nan"))
            if math.isfinite(number):
                metrics[field] = number
        certainty_grade = str(record.get("certaintyGrade") or "")
        if certainty_grade:
            metrics["manualCertaintyLevel"] = {"A+": 3, "A": 2, "B": 1}[certainty_grade]
        rows.append({
            "key": record["key"],
            "label": record["optimizationLabel"],
            "role": record["optimizationRole"],
            "decision": record["decision"],
            "certaintyGrade": certainty_grade,
            "structureTags": record.get("structureTags") or [],
            "predictedStructureTags": record.get("predictedStructureTags") or [],
            "structureReview": record.get("structureReview"),
            "pair": record["pair"],
            "interval": record["interval"],
            "time": max(0, int(safe_float(signal.get("time"), 0))),
            "updatedAt": record["updatedAt"],
            "featureTokens": dragon_wave_feedback_feature_tokens({**signal, "interval": record["interval"] or signal.get("interval")}),
            "metrics": metrics,
            "visualSignature": signal.get("visualSignature") if isinstance(signal.get("visualSignature"), dict) else None,
        })
    feature_tokens = {token for row in rows for token in row["featureTokens"]}
    supervised = dragon_wave_supervised_prototype_profile(rows)
    return {
        "datasetVersion": 10,
        "generatedAt": normalized["updatedAt"],
        "causality": "decision-time-features-only",
        "excludedOutcomeFields": ["futureReturn", "maxFavorableExcursion", "maxAdverseExcursion", "futureHigh", "futureLow"],
        "summary": {
            "total": len(rows),
            "positiveCount": sum(row["label"] == 1 for row in rows),
            "negativeCount": sum(row["label"] == -1 for row in rows),
            "pendingCount": sum(row["label"] == 0 for row in rows),
            "labeledCount": sum(row["label"] != 0 for row in rows),
            "featureCount": len(feature_tokens),
            "aPlusPrototypeCount": len(supervised["positiveAPlus"]["prototypes"]),
            "aPlusSampleCount": supervised["positiveAPlus"]["totalAPlusSamples"],
            "deniedPrototypeCount": len(supervised["negativeDenied"]["prototypes"]),
            "deniedPrototypeSampleCount": supervised["negativeDenied"]["totalDeniedSamples"],
            "visualLabeledCount": sum(row["label"] != 0 and bool(row["visualSignature"]) for row in rows),
            "visualAPlusCount": sum(row["decision"] == "confirmed" and row["certaintyGrade"] == "A+" and bool(row["visualSignature"]) for row in rows),
            "visualDeniedCount": sum(row["decision"] == "denied" and bool(row["visualSignature"]) for row in rows),
        },
        "supervisedPrototypeProfile": supervised,
        "rows": rows,
    }


def merge_dragon_wave_feedback(*documents: Any) -> dict[str, Any]:
    merged: dict[str, Any] = {"version": 1, "updatedAt": 0, "records": {}}
    for document in documents:
        normalized = normalize_dragon_wave_feedback(document)
        for key, record in normalized["records"].items():
            existing = merged["records"].get(key)
            if not existing or int(record.get("updatedAt") or 0) >= int(existing.get("updatedAt") or 0):
                merged["records"][key] = record
    return normalize_dragon_wave_feedback(merged)


def dragon_wave_feedback_for_user(user: dict[str, Any] | None) -> dict[str, Any]:
    return normalize_dragon_wave_feedback(load_user_payload(user, USER_SCOPE_DRAGON_WAVE_FEEDBACK))


def save_dragon_wave_feedback_for_user(user: dict[str, Any], incoming: Any) -> dict[str, Any]:
    merged = merge_dragon_wave_feedback(dragon_wave_feedback_for_user(user), incoming)
    save_user_payload(user, USER_SCOPE_DRAGON_WAVE_FEEDBACK, merged)
    return merged


def x_kol_system_person_sources() -> list[dict[str, Any]]:
    """Expose the shared low-frequency person roster without duplicating polling."""
    return [
        {
            **source,
            "avatar": x_kol_avatar_url(source.get("handle")),
            "systemManaged": True,
            "readOnly": True,
            "sourceGroup": "人物源",
            "createdAt": 0,
        }
        for source in important_person_sources()
        if source.get("enabled") is not False
    ]


def x_kol_sources_for_view(
    user: dict[str, Any] | None = None,
    *,
    manual_sources: list[dict[str, Any]] | None = None,
) -> list[dict[str, Any]]:
    manual = list(manual_sources) if manual_sources is not None else load_x_kol_sources(user)
    manual_handles = {
        normalize_x_handle(source.get("handle")).casefold()
        for source in manual
        if normalize_x_handle(source.get("handle"))
    }
    system = [
        source
        for source in x_kol_system_person_sources()
        if normalize_x_handle(source.get("handle")).casefold() not in manual_handles
    ]
    return [*manual, *system]


def x_kol_sources_payload(user: dict[str, Any] | None = None) -> dict[str, Any]:
    manual_sources = load_x_kol_sources(user)
    sources = x_kol_sources_for_view(user, manual_sources=manual_sources)
    return {
        "ok": True,
        "exists": bool(manual_sources),
        "sources": sources,
        "categories": [{"id": category_id, "label": label} for category_id, label in X_KOL_CATEGORIES],
        "sourceCount": len(sources),
        "enabledCount": sum(1 for source in sources if source.get("enabled") is not False),
        "manualSourceCount": len(manual_sources),
        "systemSourceCount": len(sources) - len(manual_sources),
        "hasToken": bool(x_kol_token()),
        "rssFallback": x_rss_templates(),
        "updatedAt": int(time.time() * 1000),
    }


def save_x_kol_sources_payload(payload: dict[str, Any], user: dict[str, Any] | None = None) -> dict[str, Any]:
    raw_sources = payload.get("sources") if isinstance(payload.get("sources"), list) else []
    sources: list[dict[str, Any]] = []
    seen = set()
    for raw in raw_sources:
        if not isinstance(raw, dict) or raw.get("systemManaged") is True:
            continue
        source = normalize_x_source(raw)
        if not source or source["id"] in seen:
            continue
        seen.add(source["id"])
        sources.append(source)
        if len(sources) >= 80:
            break
    saved = {
        "sources": sources,
        "updatedAt": int(time.time() * 1000),
    }
    if user:
        save_user_payload(user, USER_SCOPE_X_KOL_SOURCES, saved)
        write_json_cache(x_kol_sources_path(user), saved)
    else:
        write_json_cache(X_KOL_SOURCES_PATH, saved)
    if user and user.get("role") == "admin":
        write_json_cache(X_KOL_SOURCES_PATH, saved)
    try:
        api_cache_path("x-kol-feed").unlink(missing_ok=True)
        api_cache_path("x-kol-feed-v2").unlink(missing_ok=True)
        api_cache_path("x-kol-feed-v3").unlink(missing_ok=True)
        api_cache_path("x-kol-feed-v4").unlink(missing_ok=True)
        for path in PERSIST_CACHE_DIR.glob("api_x-kol-feed-v4-u*.json"):
            path.unlink(missing_ok=True)
    except Exception:
        pass
    wake_x_kol_realtime_worker(user)
    view_sources = x_kol_sources_for_view(user, manual_sources=sources)
    return {
        "ok": True,
        "sources": view_sources,
        "updatedAt": saved["updatedAt"],
        "categories": [{"id": category_id, "label": label} for category_id, label in X_KOL_CATEGORIES],
        "sourceCount": len(view_sources),
        "enabledCount": sum(1 for source in view_sources if source.get("enabled") is not False),
        "manualSourceCount": len(sources),
        "systemSourceCount": len(view_sources) - len(sources),
        "hasToken": bool(x_kol_token()),
    }


def normalize_todo_project(value: Any) -> dict[str, Any] | None:
    if not isinstance(value, dict):
        return None
    project_id = clean_feed_text(value.get("id"), 80)
    name = clean_feed_text(value.get("name"), 120)
    if not project_id or not name:
        return None
    return {
        "id": project_id,
        "name": name,
        "createdAt": int(safe_float(value.get("createdAt")) or time.time() * 1000),
    }


def normalize_todo_task(value: Any, project_ids: set[str], fallback_project_id: str = "") -> dict[str, Any] | None:
    if not isinstance(value, dict):
        return None
    task_id = clean_feed_text(value.get("id"), 80)
    title = clean_feed_text(value.get("title"), 220)
    if not task_id or not title:
        return None
    project_id = clean_feed_text(value.get("projectId"), 80)
    if project_ids and project_id not in project_ids:
        project_id = fallback_project_id
    priority = clean_feed_text(value.get("priority"), 20)
    if priority not in {"high", "normal", "low"}:
        priority = "normal"
    task = {
        "id": task_id,
        "projectId": project_id,
        "title": title,
        "note": clean_feed_text(value.get("note"), 1000),
        "dueAt": int(safe_float(value.get("dueAt")) or 0),
        "priority": priority,
        "done": bool(value.get("done")),
        "createdAt": int(safe_float(value.get("createdAt")) or time.time() * 1000),
    }
    updated_at = int(safe_float(value.get("updatedAt")) or 0)
    if updated_at:
        task["updatedAt"] = updated_at
    return task


def normalize_todo_payload(payload: dict[str, Any]) -> dict[str, Any]:
    raw_projects = payload.get("projects") if isinstance(payload.get("projects"), list) else []
    projects: list[dict[str, Any]] = []
    project_ids: set[str] = set()
    for raw in raw_projects[:100]:
        project = normalize_todo_project(raw)
        if not project or project["id"] in project_ids:
            continue
        project_ids.add(project["id"])
        projects.append(project)
    raw_tasks = payload.get("tasks") if isinstance(payload.get("tasks"), list) else []
    tasks: list[dict[str, Any]] = []
    task_ids: set[str] = set()
    for raw in raw_tasks[:2000]:
        task = normalize_todo_task(raw, project_ids, projects[0]["id"] if projects else "")
        if not task or task["id"] in task_ids:
            continue
        task_ids.add(task["id"])
        tasks.append(task)
    return {
        "projects": projects,
        "tasks": tasks,
        "updatedAt": int(safe_float(payload.get("updatedAt")) or time.time() * 1000),
    }


def todo_state_payload(user: dict[str, Any]) -> dict[str, Any]:
    exists = user_payload_exists(user, USER_SCOPE_TODO)
    payload = normalize_todo_payload(load_user_payload(user, USER_SCOPE_TODO))
    return {
        "ok": True,
        "storage": "sqlite",
        "exists": exists,
        "projects": payload["projects"],
        "tasks": payload["tasks"],
        "projectCount": len(payload["projects"]),
        "taskCount": len(payload["tasks"]),
        "empty": not payload["projects"] and not payload["tasks"],
        "updatedAt": payload.get("updatedAt") or int(time.time() * 1000),
    }


def save_todo_state_payload(payload: dict[str, Any], user: dict[str, Any]) -> dict[str, Any]:
    saved = normalize_todo_payload(payload)
    saved["updatedAt"] = int(time.time() * 1000)
    save_user_payload(user, USER_SCOPE_TODO, saved)
    return {
        "ok": True,
        "storage": "sqlite",
        "projects": saved["projects"],
        "tasks": saved["tasks"],
        "projectCount": len(saved["projects"]),
        "taskCount": len(saved["tasks"]),
        "updatedAt": saved["updatedAt"],
    }


def x_kol_tweet_url(handle: str, item_id: Any) -> str:
    tweet_id = clean_feed_text(item_id, 80)
    if not tweet_id:
        return f"https://x.com/{handle}"
    return f"https://x.com/{handle}/status/{tweet_id}"


def x_kol_normalize_url(value: Any, fallback_handle: str = "") -> str:
    raw = str(value or "").strip()
    if not raw:
        return f"https://x.com/{normalize_x_handle(fallback_handle)}" if normalize_x_handle(fallback_handle) else ""
    try:
        parsed = urlparse(raw)
    except Exception:
        return raw
    host = parsed.netloc.lower()
    if any(name in host for name in ("nitter", "twitter.com", "x.com")):
        parts = [part for part in parsed.path.split("/") if part]
        if len(parts) >= 3 and parts[1] == "status":
            return x_kol_tweet_url(normalize_x_handle(parts[0]), parts[2])
        if parts:
            handle = normalize_x_handle(parts[0])
            return f"https://x.com/{handle}" if handle else raw
    return raw


def x_kol_status_url_handle(value: Any) -> str:
    url = str(value or "").strip()
    try:
        parsed = urlparse(url)
    except Exception:
        return ""
    parts = [part for part in parsed.path.split("/") if part]
    if len(parts) >= 2 and parts[1] == "status":
        return normalize_x_handle(parts[0])
    return ""


def x_kol_strip_quote_url(text: str) -> str:
    return clean_feed_text(re.sub(r"\s+https?://t\.co/[A-Za-z0-9_]+$", "", text or ""), 1200)


def x_kol_quote_from_text(value: str, *, fallback_handle: str = "", url: str = "", kind: str = "引用") -> dict[str, Any]:
    text = clean_feed_text(value, 1200)
    if not text:
        return {}
    author = ""
    handle = normalize_x_handle(fallback_handle)
    match = re.match(r"^(.{1,80}?)\s+\(@([A-Za-z0-9_]{1,15})\)\s+(.+)$", text, flags=re.S)
    if match:
        author = clean_feed_text(match.group(1), 80)
        handle = normalize_x_handle(match.group(2))
        text = clean_feed_text(match.group(3), 1200)
    elif handle:
        author = f"@{handle}"
    return {
        "kind": kind,
        "authorName": author,
        "handle": handle,
        "text": text,
        "url": x_kol_normalize_url(url, handle),
    }


def x_kol_quote_display(quote: dict[str, Any], fallback: str = "原作者") -> str:
    author = clean_feed_text(quote.get("authorName"), 80)
    handle = normalize_x_handle(quote.get("handle"))
    if author and not author.startswith("@"):
        return author
    return handle or author.lstrip("@") or fallback


def x_kol_split_rss_item(source: dict[str, Any], item: dict[str, Any], text: str) -> tuple[str, dict[str, Any]]:
    title = clean_feed_text(item.get("title"), 420)
    url = str(item.get("url") or "").strip()
    url_handle = x_kol_status_url_handle(url)
    source_handle = normalize_x_handle(source.get("handle"))
    retweet_match = re.match(r"^RT\s+by\s+@([A-Za-z0-9_]{1,15})\s*:\s*(.+)$", title, flags=re.I | re.S)
    if retweet_match:
        original_handle = url_handle if url_handle and url_handle.lower() != source_handle.lower() else ""
        quote = x_kol_quote_from_text(text, fallback_handle=original_handle, url=url, kind="转推")
        label = f"转推了 {x_kol_quote_display(quote)} 的动态" if quote else "转推了一条动态"
        return label, quote

    if title and text.startswith(title):
        rest = clean_feed_text(text[len(title) :], 1200)
        if len(rest) >= 18:
            return title, x_kol_quote_from_text(rest, fallback_handle=url_handle, url=url, kind="引用")

    marker = re.search(r"\s([^\s@][^()]{1,80})\s+\(@([A-Za-z0-9_]{1,15})\)\s+", text)
    if marker and marker.start() > 12:
        main_text = clean_feed_text(text[: marker.start()], 700)
        quote_text = clean_feed_text(text[marker.start() :], 1200)
        if main_text and quote_text:
            return main_text, x_kol_quote_from_text(quote_text, fallback_handle=url_handle, url=url, kind="引用")

    return clean_feed_text(title or text, 1200), {}


def x_kol_item_key(source: dict[str, Any], item_id: Any, text: Any, published_at: Any) -> str:
    return stable_feed_id("x-kol", source.get("id"), item_id, text, published_at)


def x_kol_translation_cache_key(text: str, settings: dict[str, Any] | None = None) -> str:
    material = json.dumps(
        {
            "v": 3,
            "source": "en",
            "target": "zh",
            "text": clean_feed_text(text, 1800),
        },
        ensure_ascii=False,
        sort_keys=True,
    )
    return hashlib.sha256(material.encode("utf-8")).hexdigest()


def translation_cache_get(cache_key: str) -> dict[str, Any] | None:
    now = int(time.time())
    with AUTH_DB_LOCK, auth_db() as conn:
        row = conn.execute(
            "SELECT translation, engine, updated_at FROM translation_cache WHERE cache_key = ?",
            (cache_key,),
        ).fetchone()
        if not row:
            return None
        conn.execute(
            "UPDATE translation_cache SET hits = hits + 1, last_accessed_at = ? WHERE cache_key = ?",
            (now, cache_key),
        )
    return {
        "translation": clean_feed_text(row["translation"], 1800),
        "engine": clean_feed_text(row["engine"], 40),
        "updatedAt": int(row["updated_at"] or now) * 1000,
    }


def translation_cache_put(cache_key: str, text: str, translation: str, engine: str) -> int:
    now = int(time.time())
    source_hash = hashlib.sha256(clean_feed_text(text, 1800).encode("utf-8")).hexdigest()
    with AUTH_DB_LOCK, auth_db() as conn:
        conn.execute(
            """
            INSERT INTO translation_cache (
                cache_key, source_hash, source_lang, target_lang, translation, engine,
                hits, created_at, updated_at, last_accessed_at
            ) VALUES (?, ?, 'en', 'zh', ?, ?, 1, ?, ?, ?)
            ON CONFLICT(cache_key) DO UPDATE SET
                translation = excluded.translation,
                engine = excluded.engine,
                hits = translation_cache.hits + 1,
                updated_at = excluded.updated_at,
                last_accessed_at = excluded.last_accessed_at
            """,
            (cache_key, source_hash, translation, engine, now, now, now),
        )
        row = conn.execute("SELECT COUNT(*) AS count FROM translation_cache").fetchone()
        overflow = max(0, int(row["count"] if row else 0) - TRANSLATION_CACHE_MAX_ENTRIES)
        if overflow:
            conn.execute(
                """
                DELETE FROM translation_cache
                WHERE cache_key IN (
                    SELECT cache_key FROM translation_cache
                    ORDER BY last_accessed_at ASC
                    LIMIT ?
                )
                """,
                (overflow,),
            )
    return now * 1000


def local_translation_service_ready(timeout: float = 1.5) -> bool:
    base_url = env_value("LIBRETRANSLATE_URL") or "http://127.0.0.1:5000"
    try:
        response = requests.get(f"{base_url.rstrip('/')}/languages", timeout=max(0.5, timeout))
        return response.ok
    except Exception:
        return False


def ensure_local_translation_service(wait_seconds: int = 0) -> bool:
    global LOCAL_TRANSLATION_PROCESS
    if not env_flag("LIBRETRANSLATE_ENABLED", default=True):
        return False
    if local_translation_service_ready():
        return True

    base_url = env_value("LIBRETRANSLATE_URL") or "http://127.0.0.1:5000"
    parsed = urlparse(base_url)
    if parsed.hostname not in {"127.0.0.1", "localhost", "::1"}:
        return False
    if not env_flag("LIBRETRANSLATE_AUTOSTART", default=True):
        return False

    executable_value = env_value("LIBRETRANSLATE_EXECUTABLE")
    if executable_value:
        executable = Path(executable_value).expanduser()
    else:
        executable_name = "libretranslate.exe" if os.name == "nt" else "libretranslate"
        executable = PERSIST_CACHE_DIR / "libretranslate-venv" / ("Scripts" if os.name == "nt" else "bin") / executable_name
    if not executable.exists():
        return False

    with X_KOL_TRANSLATION_LOCK:
        if LOCAL_TRANSLATION_PROCESS is None or LOCAL_TRANSLATION_PROCESS.poll() is not None:
            port = int(parsed.port or 5000)
            args = [
                str(executable),
                "--host", parsed.hostname or "127.0.0.1",
                "--port", str(port),
                "--load-only", "en,zh",
                "--disable-web-ui",
                "--disable-files-translation",
                "--translation-cache", "all",
                "--threads", "2",
            ]
            stdout_path = PERSIST_CACHE_DIR / "libretranslate.log"
            stderr_path = PERSIST_CACHE_DIR / "libretranslate.err.log"
            creationflags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
            with stdout_path.open("ab") as stdout_file, stderr_path.open("ab") as stderr_file:
                LOCAL_TRANSLATION_PROCESS = subprocess.Popen(
                    args,
                    cwd=str(ROOT),
                    stdout=stdout_file,
                    stderr=stderr_file,
                    creationflags=creationflags,
                )

    deadline = time.time() + max(0, wait_seconds)
    while time.time() < deadline:
        if local_translation_service_ready(timeout=2):
            return True
        process = LOCAL_TRANSLATION_PROCESS
        if process is not None and process.poll() is not None:
            break
        time.sleep(1)
    return local_translation_service_ready()


def libretranslate_translate(text: str) -> str:
    ensure_local_translation_service(wait_seconds=45)
    base_url = env_value("LIBRETRANSLATE_URL") or "http://127.0.0.1:5000"
    endpoint = f"{base_url.rstrip('/')}/translate"
    body: dict[str, Any] = {
        "q": text,
        "source": "en",
        "target": "zh",
        "format": "text",
    }
    if api_key := env_value("LIBRETRANSLATE_API_KEY"):
        body["api_key"] = api_key
    timeout = max(5, min(120, int(safe_float(env_value("LIBRETRANSLATE_TIMEOUT", "45"), 45))))
    response = requests.post(
        endpoint,
        headers={**HEADERS, "Accept": "application/json", "Content-Type": "application/json"},
        json=body,
        timeout=timeout,
    )
    response.raise_for_status()
    try:
        payload = response.json()
    except ValueError as exc:
        raise RuntimeError("LibreTranslate 返回了无效响应") from exc
    translation = clean_feed_text(payload.get("translatedText"), 1800)
    if not translation:
        raise RuntimeError(clean_feed_text(payload.get("error"), 240) or "LibreTranslate 返回空译文")
    return translation


def x_kol_text_looks_english(text: Any) -> bool:
    value = clean_feed_text(text, 1800)
    if len(value) < 12:
        return False
    latin = len(re.findall(r"[A-Za-z]", value))
    cjk = len(re.findall(r"[\u4e00-\u9fff]", value))
    return latin >= 18 and latin >= max(12, cjk * 4)


def x_kol_translate_payload(payload: dict[str, Any], settings: dict[str, Any] | None = None) -> dict[str, Any]:
    text = clean_feed_text(
        payload.get("text")
        or payload.get("translationText")
        or payload.get("sourceText")
        or payload.get("body")
        or payload.get("content"),
        1800,
    )
    if not text:
        return {"ok": False, "error": "empty text"}
    if not x_kol_text_looks_english(text) and not payload.get("force"):
        return {"ok": True, "skipped": True, "translation": ""}

    cache_key = x_kol_translation_cache_key(text)
    cached = translation_cache_get(cache_key)
    if cached and cached.get("translation"):
        return {"ok": True, "cached": True, **cached}

    resolved_settings = settings or system_llm_settings()
    errors: list[str] = []
    if env_flag("LIBRETRANSLATE_ENABLED", default=True):
        try:
            translation = libretranslate_translate(text)
            updated_at = translation_cache_put(cache_key, text, translation, "libretranslate")
            return {
                "ok": True,
                "cached": False,
                "engine": "libretranslate",
                "translation": translation,
                "updatedAt": updated_at,
            }
        except Exception as exc:
            errors.append(f"本地翻译不可用：{clean_feed_text(exc, 260)}")

    if not env_flag("TRANSLATION_LLM_FALLBACK", default=False):
        return {"ok": False, "error": "；".join(errors) or "本地翻译服务未启用"}
    if not deepseek_enabled(resolved_settings):
        errors.append("未配置大模型 API Key")
        return {"ok": False, "error": "；".join(errors)}

    messages = [
        {
            "role": "system",
            "content": (
                "你是交易信息流翻译助手。把英文 X/Twitter 动态翻译成自然、简洁的中文。"
                "保留代币符号、股票代码、@账号、URL、数字、百分比和专有名词；不要解释，不要扩写，不要输出 Markdown。"
                "只返回 JSON：{\"translation\":\"中文译文\"}。"
            ),
        },
        {"role": "user", "content": json.dumps({"text": text}, ensure_ascii=False)},
    ]
    try:
        response = deepseek_chat(messages, resolved_settings)
    except Exception as exc:
        errors.append(f"大模型回退失败：{clean_feed_text(exc, 260)}")
        return {"ok": False, "error": "；".join(errors)}
    content = response.get("choices", [{}])[0].get("message", {}).get("content", "")
    parsed = deepseek_extract_json(content)
    translation = clean_feed_text(parsed.get("translation") or parsed.get("text") or content, 1800)
    if not translation:
        return {"ok": False, "error": "empty translation"}

    translation_engine = "codex-cli" if response.get("_provider") == "codex-cli" else "llm"
    updated_at = translation_cache_put(cache_key, text, translation, translation_engine)
    return {
        "ok": True,
        "cached": False,
        "engine": translation_engine,
        "translation": translation,
        "updatedAt": updated_at,
    }


def x_kol_fetch_api_source(
    source: dict[str, Any],
    token: str,
    *,
    history_recovery: bool = False,
) -> dict[str, Any]:
    """Fetch only owner-account increments; never replay a fixed recent-history window."""
    if not X_OFFICIAL_API_USER_APPROVED:
        raise RuntimeError("已按用户要求停用 X 官方 API")
    if not x_kol_official_paid_source_allowed(source):
        raise RuntimeError("X 官方 API 仅允许读取个人账号")

    handle = normalize_x_handle(source.get("handle"))
    headers = {
        **HEADERS,
        "Authorization": f"Bearer {token}",
        "Accept": "application/json",
    }
    previous_profile = x_kol_api_cached_profile(handle)
    previous_count_raw = previous_profile.get("tweetCount")
    previous_count = int(safe_float(previous_count_raw)) if previous_count_raw is not None else None
    profile_is_fresh = previous_profile.get("refreshedDate") == x_kol_api_cost_day()
    user = dict(previous_profile)

    if not user.get("id") or (history_recovery and not profile_is_fresh):
        claimed, budget = x_kol_api_cost_claim_request("owner-profile", profile_lookup=True)
        if not claimed:
            raise RuntimeError(f"X 付费读取已停止：今日预算或账号查询上限已到 ({budget['estimatedUsd']:.3f} USD)")
        user_response = requests.get(
            f"https://api.twitter.com/2/users/by/username/{quote(handle)}",
            headers=headers,
            params={"user.fields": "description,profile_image_url,verified,public_metrics"},
            timeout=16,
        )
        user_response.raise_for_status()
        user_payload = user_response.json()
        raw_user = user_payload.get("data") if isinstance(user_payload, dict) else {}
        if not isinstance(raw_user, dict) or not raw_user.get("id"):
            raise ValueError(f"{handle} 未返回用户信息")
        public_metrics = raw_user.get("public_metrics") if isinstance(raw_user.get("public_metrics"), dict) else {}
        current_count_raw = public_metrics.get("tweet_count")
        remote_count = int(safe_float(current_count_raw)) if current_count_raw is not None else None
        user = {
            "id": str(raw_user.get("id")),
            "name": clean_feed_text(raw_user.get("name"), 120),
            "username": normalize_x_handle(raw_user.get("username") or handle),
            "profile_image_url": str(raw_user.get("profile_image_url") or ""),
            "verified": bool(raw_user.get("verified")),
            # tweetCount is the last completely processed baseline. Keep a fresh
            # observation separate until the incremental timeline request succeeds.
            "tweetCount": previous_count,
            "remoteTweetCount": remote_count,
            "refreshedDate": x_kol_api_cost_day(),
        }
        x_kol_api_cost_record_resources(user_reads=1, handle=handle, profile=user)

    current_count_raw = user.get("remoteTweetCount", user.get("tweetCount"))
    current_count = int(safe_float(current_count_raw)) if current_count_raw is not None else None
    history_delta: int | None = None
    if history_recovery:
        if previous_count is None or current_count is None:
            baseline_profile = {**user, "tweetCount": current_count, "remoteTweetCount": current_count}
            x_kol_api_cost_record_resources(handle=handle, profile=baseline_profile)
            return {
                "source": {
                    **source,
                    "displayName": user.get("name") or source.get("displayName") or handle,
                    "avatar": x_kol_avatar_url(handle, user.get("profile_image_url") or source.get("avatar")),
                    "status": "ok",
                    "provider": "x-api",
                    "itemsReturned": 0,
                    "historyDelta": 0,
                    "historyBaselineOnly": True,
                    "quotedPostsExcluded": True,
                    "costGuard": x_kol_api_cost_snapshot(),
                    "lastOkAt": int(time.time() * 1000),
                    "lastCheckAt": int(time.time() * 1000),
                },
                "items": [],
            }
        history_delta = max(0, current_count - previous_count)
        if history_delta <= 0:
            baseline_profile = {**user, "tweetCount": current_count, "remoteTweetCount": current_count}
            x_kol_api_cost_record_resources(handle=handle, profile=baseline_profile)
            return {
                "source": {
                    **source,
                    "displayName": user.get("name") or source.get("displayName") or handle,
                    "avatar": x_kol_avatar_url(handle, user.get("profile_image_url") or source.get("avatar")),
                    "status": "ok",
                    "provider": "x-api",
                    "itemsReturned": 0,
                    "historyDelta": 0,
                    "quotedPostsExcluded": True,
                    "costGuard": x_kol_api_cost_snapshot(),
                    "lastOkAt": int(time.time() * 1000),
                    "lastCheckAt": int(time.time() * 1000),
                },
                "items": [],
            }

    budget_before_timeline = x_kol_api_cost_snapshot()
    remaining_posts = int(safe_float(budget_before_timeline.get("remainingPostReads")) or 0)
    if remaining_posts < 5:
        raise RuntimeError(
            f"X 付费读取已停止：今日剩余额度不足一次最小增量请求 ({budget_before_timeline['estimatedUsd']:.3f} USD)"
        )
    desired = history_delta if history_delta is not None else 5
    max_results = min(10, remaining_posts, max(5, desired))
    claimed, budget = x_kol_api_cost_claim_request("owner-timeline-increment", requires_post_capacity=True)
    if not claimed:
        raise RuntimeError(f"X 付费读取已停止：今日预算或请求上限已到 ({budget['estimatedUsd']:.3f} USD)")

    params = {
        "max_results": str(max_results),
        # referenced_tweets gives only the relationship type. Omitting expansions avoids
        # paying for and downloading the quoted original Post and its author.
        "tweet.fields": "created_at,public_metrics,entities,lang,referenced_tweets",
    }
    exclude = []
    if not x_kol_include_retweets():
        exclude.append("retweets")
    if not x_kol_include_replies():
        exclude.append("replies")
    if exclude:
        params["exclude"] = ",".join(exclude)
    since_id = x_kol_api_since_id(handle)
    if since_id:
        params["since_id"] = since_id

    tweets_response = requests.get(
        f"https://api.twitter.com/2/users/{user['id']}/tweets",
        headers=headers,
        params=params,
        timeout=18,
    )
    tweets_response.raise_for_status()
    tweet_payload = tweets_response.json()
    returned_tweets = [
        tweet
        for tweet in (tweet_payload.get("data") if isinstance(tweet_payload, dict) else []) or []
        if isinstance(tweet, dict)
    ]
    returned_ids = [str(tweet.get("id") or "") for tweet in returned_tweets if tweet.get("id")]
    latest_id = ""
    if returned_ids:
        latest_id = max(returned_ids, key=lambda value: int(value) if value.isdigit() else 0)
    accepted, budget_after = x_kol_api_cost_record_resources(
        post_ids=returned_ids,
        handle=handle,
        profile={**user, "tweetCount": current_count, "remoteTweetCount": current_count},
        since_id=latest_id or since_id,
    )
    if not accepted:
        raise RuntimeError("X 付费读取返回量超过今日硬预算，已停止处理")

    rows: list[dict[str, Any]] = []
    for tweet in returned_tweets:
        references = [ref for ref in tweet.get("referenced_tweets") or [] if isinstance(ref, dict)]
        ref_types = [str(ref.get("type") or "") for ref in references]
        if "quoted" in ref_types:
            continue
        text = clean_feed_text(tweet.get("text"), 1200)
        if not text or not x_kol_item_matches(source, text):
            continue
        published_at = parse_feed_datetime(tweet.get("created_at")) or int(time.time() * 1000)
        metrics = tweet.get("public_metrics") if isinstance(tweet.get("public_metrics"), dict) else {}
        tweet_id = str(tweet.get("id") or "")
        main_text = x_kol_strip_quote_url(text)
        rows.append(
            {
                "id": x_kol_item_key(source, tweet_id, text, published_at),
                "tweetId": tweet_id,
                "text": main_text,
                "fullText": text,
                "quote": {},
                "title": clean_feed_text(main_text, 120),
                "url": x_kol_tweet_url(handle, tweet_id),
                "publishedAt": published_at,
                "sourceId": source["id"],
                "sourceName": user.get("name") or source.get("displayName") or handle,
                "handle": handle,
                "avatar": x_kol_avatar_url(handle, user.get("profile_image_url") or source.get("avatar")),
                "metrics": {
                    "reply": int(safe_float(metrics.get("reply_count"))),
                    "repost": int(safe_float(metrics.get("retweet_count"))),
                    "like": int(safe_float(metrics.get("like_count"))),
                    "quote": int(safe_float(metrics.get("quote_count"))),
                    "view": int(safe_float(metrics.get("impression_count"))),
                },
                "matchedKeywords": x_kol_keyword_hits(source, text),
                "entryType": ref_types[0] if ref_types else "tweet",
                "provider": "x-api",
            }
        )

    return {
        "source": {
            **source,
            "displayName": user.get("name") or source.get("displayName") or handle,
            "avatar": x_kol_avatar_url(handle, user.get("profile_image_url") or source.get("avatar")),
            "status": "ok",
            "provider": "x-api",
            "itemsReturned": len(rows),
            "resourcesReturned": len(returned_ids),
            "historyDelta": history_delta,
            "quotedPostsExcluded": True,
            "incrementalSinceId": since_id,
            "costGuard": budget_after,
            "includeReplies": x_kol_include_replies(),
            "includeRetweets": x_kol_include_retweets(),
            "lastOkAt": int(time.time() * 1000),
            "lastCheckAt": int(time.time() * 1000),
        },
        "items": rows,
    }


def x_kol_rss_rejection_reason(parsed: dict[str, Any]) -> str:
    feed = parsed.get("feed") if isinstance(parsed.get("feed"), dict) else {}
    sample = " ".join([
        clean_feed_text(feed.get("title"), 300),
        *[
            clean_feed_text((item or {}).get("title") or (item or {}).get("summary"), 500)
            for item in (parsed.get("items") or [])[:3]
            if isinstance(item, dict)
        ],
    ]).lower()
    blocked_markers = (
        "rss reader not yet whitelisted",
        "rss reader not yet whitelist",
        "please send an email rss",
        "just a moment... enable javascript and cookies",
    )
    return next((marker for marker in blocked_markers if marker in sample), "")


def _gmgn_trench_x_external_url(value: Any, limit: int = 1200) -> str:
    raw = str(value or "").strip()
    try:
        parsed = urlparse(raw)
    except Exception:
        return ""
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        return ""
    return raw[:limit]


def gmgn_trench_x_post_from_fxtwitter(payload: dict[str, Any], status_id: str) -> dict[str, Any]:
    """Normalize one public post returned for a GMGN-provided status id."""
    status = payload.get("status") if isinstance(payload.get("status"), dict) else {}
    if not status:
        return {}
    author = status.get("author") if isinstance(status.get("author"), dict) else {}
    if not author and isinstance(payload.get("author"), dict):
        author = payload["author"]
    handle = normalize_x_handle(author.get("screen_name") or author.get("username"))
    post_id = clean_feed_text(status.get("id") or status_id, 40)
    text = clean_feed_text(status.get("text") or status.get("full_text"), 4000)

    published_at = int(safe_float(status.get("created_timestamp")))
    if published_at and published_at < 10_000_000_000:
        published_at *= 1000
    if not published_at:
        published_at = parse_feed_datetime(status.get("created_at"))

    media = status.get("media") if isinstance(status.get("media"), dict) else {}
    media_rows: list[dict[str, Any]] = []
    seen_media: set[str] = set()

    def append_media(item: Any, kind: str) -> None:
        if not isinstance(item, dict):
            return
        preview = _gmgn_trench_x_external_url(
            item.get("url")
            or item.get("media_url_https")
            or item.get("media_url")
            or item.get("thumbnail_url")
            or item.get("thumb_url")
        )
        playback = ""
        formats = item.get("formats") if isinstance(item.get("formats"), list) else []
        for fmt in reversed(formats):
            if not isinstance(fmt, dict):
                continue
            playback = _gmgn_trench_x_external_url(fmt.get("url"))
            if playback:
                break
        identity = preview or playback
        if not identity or identity in seen_media:
            return
        seen_media.add(identity)
        media_rows.append({
            "type": kind,
            "previewUrl": preview,
            "playbackUrl": playback,
            "width": int(safe_float(item.get("width"))),
            "height": int(safe_float(item.get("height"))),
        })

    for item in media.get("photos") if isinstance(media.get("photos"), list) else []:
        append_media(item, "photo")
    for item in media.get("videos") if isinstance(media.get("videos"), list) else []:
        append_media(item, "video")
    for item in media.get("all") if isinstance(media.get("all"), list) else []:
        item_type = clean_feed_text((item or {}).get("type") if isinstance(item, dict) else "", 20).lower()
        append_media(item, "video" if item_type in {"video", "gif", "animated_gif"} else "photo")

    if not text and not media_rows:
        return {}
    post_url = _gmgn_trench_x_external_url(status.get("url"))
    if not post_url and handle and post_id:
        post_url = x_kol_tweet_url(handle, post_id)
    return {
        "statusId": post_id,
        "url": post_url,
        "text": text,
        "publishedAt": published_at,
        "lang": clean_feed_text(status.get("lang"), 20),
        "author": {
            "name": clean_feed_text(author.get("name") or (f"@{handle}" if handle else ""), 120),
            "handle": handle,
            "avatar": _gmgn_trench_x_external_url(author.get("avatar_url") or author.get("profile_image_url")),
            "followers": int(safe_float(author.get("followers") or author.get("followers_count"))),
        },
        "metrics": {
            "reply": int(safe_float(status.get("replies") or status.get("reply_count"))),
            "repost": int(safe_float(status.get("reposts") or status.get("retweets") or status.get("retweet_count"))),
            "like": int(safe_float(status.get("likes") or status.get("favorite_count"))),
            "quote": int(safe_float(status.get("quotes") or status.get("quote_count"))),
            "view": int(safe_float(status.get("views") or status.get("view_count"))),
        },
        "media": media_rows[:4],
    }


def _gmgn_trench_x_post_cached(status_id: str) -> dict[str, Any] | None:
    now = time.time()
    with GMGN_TRENCH_X_POST_CACHE_LOCK:
        cached = GMGN_TRENCH_X_POST_CACHE.get(status_id)
        if not cached:
            return None
        expires_at, payload = cached
        if expires_at <= now:
            GMGN_TRENCH_X_POST_CACHE.pop(status_id, None)
            return None
        return {**payload, "cached": True}


def _store_gmgn_trench_x_post(status_id: str, payload: dict[str, Any], ttl_seconds: float) -> None:
    with GMGN_TRENCH_X_POST_CACHE_LOCK:
        if len(GMGN_TRENCH_X_POST_CACHE) >= 600:
            oldest = min(GMGN_TRENCH_X_POST_CACHE, key=lambda key: GMGN_TRENCH_X_POST_CACHE[key][0])
            GMGN_TRENCH_X_POST_CACHE.pop(oldest, None)
        GMGN_TRENCH_X_POST_CACHE[status_id] = (time.time() + max(60.0, ttl_seconds), dict(payload))


def gmgn_trench_x_post_payload(status_id: Any, *, session: Any = None) -> dict[str, Any]:
    """Fetch one original post lazily; never prefetch the GMGN trench history."""
    global GMGN_TRENCH_X_POST_NEXT_REQUEST_AT
    normalized_id = clean_feed_text(status_id, 40)
    if not re.fullmatch(r"\d{2,20}", normalized_id):
        raise ValueError("原帖编号无效")
    cached = _gmgn_trench_x_post_cached(normalized_id)
    if cached is not None:
        return cached

    with GMGN_TRENCH_X_POST_REQUEST_LOCK:
        cached = _gmgn_trench_x_post_cached(normalized_id)
        if cached is not None:
            return cached
        delay = GMGN_TRENCH_X_POST_NEXT_REQUEST_AT - time.monotonic()
        if delay > 0:
            time.sleep(delay)
        GMGN_TRENCH_X_POST_NEXT_REQUEST_AT = time.monotonic() + GMGN_TRENCH_X_POST_MIN_INTERVAL_SECONDS

        url = f"{X_KOL_FXTWITTER_BASE_URL}/2/status/{quote(normalized_id, safe='')}"
        result: dict[str, Any]
        ttl = GMGN_TRENCH_X_POST_NEGATIVE_TTL_SECONDS
        try:
            client = session or requests
            response = client.get(
                url,
                headers={
                    "User-Agent": "XingyunMarketDashboard/1.0 (+https://github.com/whitestar224/market-hot-dashboard)",
                    "Accept": "application/json",
                },
                timeout=(min(3.0, X_KOL_FXTWITTER_TIMEOUT_SECONDS), X_KOL_FXTWITTER_TIMEOUT_SECONDS),
            )
            if int(getattr(response, "status_code", 0) or 0) == 429:
                result = {
                    "ok": False,
                    "status": "rate_limited",
                    "statusId": normalized_id,
                    "error": "原帖公开源请求较多，请稍后再悬停查看",
                }
            else:
                response.raise_for_status()
                raw = response.json()
                if not isinstance(raw, dict):
                    raise ValueError("原帖公开源返回格式异常")
                code = int(safe_float(raw.get("code"), 200))
                post = gmgn_trench_x_post_from_fxtwitter(raw, normalized_id) if code == 200 else {}
                if post:
                    ttl = GMGN_TRENCH_X_POST_CACHE_TTL_SECONDS
                    result = {
                        "ok": True,
                        "status": "ok",
                        "statusId": normalized_id,
                        "post": post,
                        "source": "fxtwitter-public",
                    }
                else:
                    result = {
                        "ok": False,
                        "status": "unavailable",
                        "statusId": normalized_id,
                        "error": "原帖可能已删除、受限或暂时不可读取",
                    }
        except Exception as exc:
            result = {
                "ok": False,
                "status": "unavailable",
                "statusId": normalized_id,
                "error": clean_feed_text(exc, 180) or "原帖暂时不可读取",
            }
        result["cached"] = False
        result["fetchedAt"] = int(time.time() * 1000)
        _store_gmgn_trench_x_post(normalized_id, result, ttl)
        return result


def x_kol_fxtwitter_quote(status: dict[str, Any], fallback_handle: str) -> dict[str, Any]:
    quoted = status.get("quote") if isinstance(status.get("quote"), dict) else {}
    if not quoted:
        return {}
    author = quoted.get("author") if isinstance(quoted.get("author"), dict) else {}
    quote_handle = normalize_x_handle(author.get("screen_name"))
    text = clean_feed_text(quoted.get("text"), 1200)
    quote_id = str(quoted.get("id") or "")
    if not text:
        return {}
    return {
        "kind": "引用",
        "authorName": author.get("name") or (f"@{quote_handle}" if quote_handle else ""),
        "handle": quote_handle,
        "text": text,
        "url": str(quoted.get("url") or "") or (x_kol_tweet_url(quote_handle or fallback_handle, quote_id) if quote_id else ""),
        "avatar": x_kol_avatar_url(quote_handle, author.get("avatar_url")),
        "publishedAt": (
            int(safe_float(quoted.get("created_timestamp")) * 1000)
            or parse_feed_datetime(quoted.get("created_at"))
        ),
    }


def x_kol_parse_fxtwitter_timeline(
    source: dict[str, Any],
    payload: dict[str, Any],
    url: str,
) -> dict[str, Any]:
    if int(safe_float(payload.get("code"))) not in {0, 200}:
        raise ValueError(clean_feed_text(payload.get("message") or f"FxTwitter code {payload.get('code')}", 240))
    results = payload.get("results") if isinstance(payload.get("results"), list) else []
    handle = normalize_x_handle(source.get("handle"))
    fetch_limit = x_kol_fetch_limit()
    rows: list[dict[str, Any]] = []
    for status in results:
        if not isinstance(status, dict) or str(status.get("type") or "status") != "status":
            continue
        text = clean_feed_text(status.get("text"), 1200)
        if not text or not x_kol_item_matches(source, text):
            continue
        reposted_by = status.get("reposted_by") if isinstance(status.get("reposted_by"), dict) else {}
        is_retweet = bool(reposted_by)
        is_reply = bool(status.get("replying_to"))
        if is_retweet and not x_kol_include_retweets():
            continue
        if is_reply and not x_kol_include_replies():
            continue
        author = status.get("author") if isinstance(status.get("author"), dict) else {}
        source_author = reposted_by or author
        tweet_id = str(status.get("id") or "")
        if not tweet_id:
            continue
        published_at = (
            int(safe_float(status.get("created_timestamp")) * 1000)
            or parse_feed_datetime(status.get("created_at"))
        )
        quote_card = x_kol_fxtwitter_quote(status, handle)
        rows.append({
            "id": x_kol_item_key(source, tweet_id, text, published_at),
            "tweetId": tweet_id,
            "text": x_kol_strip_quote_url(text) if quote_card else text,
            "fullText": text,
            "quote": quote_card,
            "title": clean_feed_text(text, 120),
            "url": str(status.get("url") or "") or x_kol_tweet_url(handle, tweet_id),
            "publishedAt": published_at,
            "sourceId": source["id"],
            "sourceName": source_author.get("name") or source.get("displayName") or handle,
            "handle": handle,
            "avatar": x_kol_avatar_url(handle, source_author.get("avatar_url") or source.get("avatar")),
            "metrics": {
                "reply": int(safe_float(status.get("replies"))),
                "repost": int(safe_float(status.get("reposts") or status.get("retweets"))),
                "like": int(safe_float(status.get("likes"))),
                "quote": int(safe_float(status.get("quotes"))),
                "view": int(safe_float(status.get("views"))),
            },
            "matchedKeywords": x_kol_keyword_hits(source, text),
            "entryType": "retweeted" if is_retweet else ("replied_to" if is_reply else "tweet"),
            "provider": "fxtwitter",
        })
    rows.sort(key=lambda row: int(safe_float(row.get("publishedAt"))), reverse=True)
    first = rows[0] if rows else {}
    return {
        "source": {
            **source,
            "displayName": first.get("sourceName") or source.get("displayName") or handle,
            "avatar": first.get("avatar") or source.get("avatar") or "",
            "status": "ok",
            "provider": "rss",
            "upstreamSource": "fxtwitter",
            "feedUrl": url,
            "itemsReturned": min(len(rows), fetch_limit),
            "fetchLimit": fetch_limit,
            "limited": True,
            "lastOkAt": int(time.time() * 1000),
            "lastCheckAt": int(time.time() * 1000),
        },
        "items": rows[:fetch_limit],
    }


def x_kol_fetch_fxtwitter_timeline(source: dict[str, Any]) -> dict[str, Any]:
    handle = normalize_x_handle(source.get("handle"))
    url = f"{X_KOL_FXTWITTER_BASE_URL}/2/profile/{quote(handle, safe='')}/statuses"
    try:
        response = requests.get(
            url,
            headers={
                "User-Agent": "XingyunMarketDashboard/1.0 (+https://github.com/whitestar224/market-hot-dashboard)",
                "Accept": "application/json",
            },
            timeout=(min(3.0, X_KOL_FXTWITTER_TIMEOUT_SECONDS), X_KOL_FXTWITTER_TIMEOUT_SECONDS),
        )
        response.raise_for_status()
        payload = response.json()
        if not isinstance(payload, dict):
            raise ValueError("FxTwitter 返回格式异常")
        return x_kol_parse_fxtwitter_timeline(source, payload, url)
    except Exception as exc:
        return {
            "source": {
                **source,
                "status": "error",
                "provider": "rss",
                "upstreamSource": "fxtwitter",
                "error": "免费时间线备用源暂时不可用",
                "upstreamError": clean_feed_text(exc, 240),
                "lastCheckAt": int(time.time() * 1000),
            },
            "items": [],
        }


def x_kol_public_timeline_tweet(content: dict[str, Any]) -> dict[str, Any]:
    tweet = content.get("tweet")
    if isinstance(tweet, dict):
        return tweet
    item_content = content.get("itemContent") if isinstance(content.get("itemContent"), dict) else {}
    result = (
        ((item_content.get("tweet_results") or {}).get("result"))
        if isinstance(item_content.get("tweet_results"), dict)
        else None
    )
    if isinstance(result, dict):
        legacy = result.get("legacy") if isinstance(result.get("legacy"), dict) else {}
        if legacy:
            return {**legacy, "id_str": legacy.get("id_str") or result.get("rest_id")}
    return {}


def x_kol_parse_public_timeline(
    source: dict[str, Any],
    content: bytes,
    url: str,
) -> dict[str, Any]:
    raw = content.decode("utf-8", errors="replace")
    match = re.search(
        r'<script[^>]+id=["\']__NEXT_DATA__["\'][^>]*>(.*?)</script>',
        raw,
        flags=re.I | re.S,
    )
    if not match:
        raise ValueError("X 公开时间线未返回可解析数据")
    try:
        # __NEXT_DATA__ is already JSON. HTML-unescaping it can turn encoded
        # quotes inside post text into raw quotes and corrupt otherwise valid JSON.
        document = json.loads(match.group(1))
    except Exception as exc:
        raise ValueError("X 公开时间线数据格式异常") from exc
    page_props = ((document.get("props") or {}).get("pageProps")) if isinstance(document, dict) else {}
    if not isinstance(page_props, dict) or not isinstance(page_props.get("timeline"), dict):
        raise ValueError("X 公开时间线缺少 timeline 数据")

    handle = normalize_x_handle(source.get("handle"))
    fetch_limit = x_kol_fetch_limit()
    rows: list[dict[str, Any]] = []
    for entry in page_props["timeline"].get("entries") or []:
        if not isinstance(entry, dict):
            continue
        content_node = entry.get("content") if isinstance(entry.get("content"), dict) else {}
        tweet = x_kol_public_timeline_tweet(content_node)
        if not tweet:
            continue
        text = clean_feed_text(tweet.get("full_text") or tweet.get("text"), 1200)
        if not text or not x_kol_item_matches(source, text):
            continue
        is_retweet = isinstance(tweet.get("retweeted_status"), dict) or text.upper().startswith("RT @")
        is_reply = bool(tweet.get("in_reply_to_status_id_str") or tweet.get("in_reply_to_user_id_str"))
        if is_retweet and not x_kol_include_retweets():
            continue
        if is_reply and not x_kol_include_replies():
            continue
        user = tweet.get("user") if isinstance(tweet.get("user"), dict) else {}
        tweet_id = str(tweet.get("id_str") or tweet.get("id") or "")
        if not tweet_id:
            continue
        published_at = parse_feed_datetime(tweet.get("created_at"))
        tweet_handle = normalize_x_handle(user.get("screen_name")) or handle
        permalink = x_kol_normalize_url(tweet.get("permalink"), tweet_handle) or x_kol_tweet_url(tweet_handle, tweet_id)
        quoted = tweet.get("quoted_status") if isinstance(tweet.get("quoted_status"), dict) else {}
        quote_card: dict[str, Any] = {}
        if quoted:
            quote_user = quoted.get("user") if isinstance(quoted.get("user"), dict) else {}
            quote_handle = normalize_x_handle(quote_user.get("screen_name"))
            quote_text = clean_feed_text(quoted.get("full_text") or quoted.get("text"), 1200)
            if quote_text:
                quote_id = str(quoted.get("id_str") or quoted.get("id") or "")
                quote_card = {
                    "kind": "引用",
                    "authorName": quote_user.get("name") or (f"@{quote_handle}" if quote_handle else ""),
                    "handle": quote_handle,
                    "text": quote_text,
                    "url": x_kol_tweet_url(quote_handle or handle, quote_id) if quote_id else "",
                    "avatar": x_kol_avatar_url(quote_handle, quote_user.get("profile_image_url_https")),
                    "publishedAt": parse_feed_datetime(quoted.get("created_at")),
                }
        rows.append({
            "id": x_kol_item_key(source, tweet_id, text, published_at),
            "tweetId": tweet_id,
            "text": x_kol_strip_quote_url(text) if quote_card else text,
            "fullText": text,
            "quote": quote_card,
            "title": clean_feed_text(text, 120),
            "url": permalink,
            "publishedAt": published_at,
            "sourceId": source["id"],
            "sourceName": user.get("name") or source.get("displayName") or handle,
            "handle": handle,
            "avatar": x_kol_avatar_url(handle, user.get("profile_image_url_https") or source.get("avatar")),
            "metrics": {
                "reply": int(safe_float(tweet.get("reply_count"))),
                "repost": int(safe_float(tweet.get("retweet_count"))),
                "like": int(safe_float(tweet.get("favorite_count"))),
                "quote": int(safe_float(tweet.get("quote_count"))),
                "view": 0,
            },
            "matchedKeywords": x_kol_keyword_hits(source, text),
            "entryType": "retweeted" if is_retweet else ("replied_to" if is_reply else "tweet"),
            "provider": "x-public-timeline",
        })
    rows.sort(key=lambda row: int(safe_float(row.get("publishedAt"))), reverse=True)
    first = rows[0] if rows else {}
    return {
        "source": {
            **source,
            "displayName": first.get("sourceName") or source.get("displayName") or handle,
            "avatar": first.get("avatar") or source.get("avatar") or "",
            "status": "ok",
            "provider": "rss",
            "upstreamSource": "x-public-timeline",
            "feedUrl": url,
            "itemsReturned": min(len(rows), fetch_limit),
            "fetchLimit": fetch_limit,
            "limited": True,
            "lastOkAt": int(time.time() * 1000),
            "lastCheckAt": int(time.time() * 1000),
        },
        "items": rows[:fetch_limit],
    }


def x_kol_fetch_public_timeline(source: dict[str, Any]) -> dict[str, Any]:
    handle = normalize_x_handle(source.get("handle"))
    url = f"https://syndication.twitter.com/srv/timeline-profile/screen-name/{quote(handle, safe='')}?dnt=true"
    try:
        response = requests.get(
            url,
            headers={**HEADERS, "Accept": "text/html,application/xhtml+xml"},
            timeout=(min(3.0, X_KOL_PUBLIC_TIMELINE_TIMEOUT_SECONDS), X_KOL_PUBLIC_TIMELINE_TIMEOUT_SECONDS),
        )
        response.raise_for_status()
        if len(response.content) > RSS_FETCH_MAX_BYTES:
            raise ValueError("X 公开时间线响应过大")
        return x_kol_parse_public_timeline(source, response.content, url)
    except Exception as exc:
        return {
            "source": {
                **source,
                "status": "error",
                "provider": "rss",
                "upstreamSource": "x-public-timeline",
                "error": "免费公开时间线暂时不可用",
                "upstreamError": clean_feed_text(exc, 240),
                "lastCheckAt": int(time.time() * 1000),
            },
            "items": [],
        }


def x_kol_fetch_rss_template(
    source: dict[str, Any],
    template: str,
    *,
    timeout_seconds: float = X_KOL_RSS_TIMEOUT_SECONDS,
) -> dict[str, Any]:
    handle = source["handle"]
    url = (
        template.replace("{handle}", quote(handle, safe=""))
        if "{handle}" in template
        else f"{template.rstrip('/')}/{quote(handle, safe='')}"
    )
    started_at = time.monotonic()
    try:
        response = requests.get(
            url,
            headers={
                **HEADERS,
                "User-Agent": X_KOL_RSS_USER_AGENT,
                "Accept": "application/rss+xml, application/atom+xml, text/xml, */*",
                "Accept-Language": "en-US,en;q=0.9",
            },
            timeout=(min(2.5, timeout_seconds), timeout_seconds),
        )
        response.raise_for_status()
        parsed = parse_xml_feed(response.content[: RSS_FETCH_MAX_BYTES + 1].lstrip(), url)
        rejection = x_kol_rss_rejection_reason(parsed)
        if rejection:
            raise ValueError(f"RSS mirror rejected this reader: {rejection}")
        rows = []
        for item in parsed.get("items") or []:
            text = clean_feed_text(item.get("summary") or item.get("title"), 1200)
            if not text or not x_kol_item_matches(source, text):
                continue
            main_text, quote_card = x_kol_split_rss_item(source, item, text)
            published_at = int(safe_float(item.get("publishedAt")) or 0)
            rows.append(
                {
                    "id": x_kol_item_key(source, item.get("id") or item.get("url"), text, published_at),
                    "tweetId": item.get("id") or "",
                    "text": main_text,
                    "fullText": text,
                    "quote": quote_card,
                    "title": clean_feed_text(main_text, 120),
                    "url": x_kol_normalize_url(item.get("url"), handle) or f"https://x.com/{handle}",
                    "publishedAt": published_at,
                    "sourceId": source["id"],
                    "sourceName": source.get("displayName") or parsed.get("feed", {}).get("title") or handle,
                    "handle": handle,
                    "avatar": source.get("avatar") or "",
                    "metrics": {},
                    "matchedKeywords": x_kol_keyword_hits(source, text),
                    "entryType": "rss",
                    "provider": "rss",
                }
            )
        return {
            "ok": True,
            "template": template,
            "url": url,
            "rows": rows,
            "elapsed": time.monotonic() - started_at,
        }
    except Exception as exc:
        return {
            "ok": False,
            "template": template,
            "url": url,
            "rows": [],
            "elapsed": time.monotonic() - started_at,
            "error": str(exc),
        }


def x_kol_rss_result_payload(
    source: dict[str, Any],
    results: list[dict[str, Any]],
) -> dict[str, Any]:
    handle = source["handle"]
    fetch_limit = x_kol_fetch_limit()
    successful = [result for result in results if result.get("ok")]
    rows = [row for result in successful for row in result.get("rows") or []]
    if rows:
        deduped = {row["id"]: row for row in rows}
        sorted_rows = sorted(
            deduped.values(),
            key=lambda row: int(safe_float(row.get("publishedAt"))),
            reverse=True,
        )
        successful.sort(
            key=lambda result: (
                max((int(safe_float(row.get("publishedAt"))) for row in result.get("rows") or []), default=0),
                -safe_float(result.get("elapsed")),
            ),
            reverse=True,
        )
        selected = successful[0]
        with X_KOL_RSS_PREFERENCE_LOCK:
            X_KOL_RSS_PREFERRED_TEMPLATES[handle.lower()] = str(selected.get("template") or "")
        return {
            "source": {
                **source,
                "status": "ok",
                "provider": "rss",
                "feedUrl": selected.get("url") or "",
                "feedUrls": [result.get("url") for result in successful if result.get("url")],
                "itemsReturned": min(len(sorted_rows), fetch_limit),
                "fetchLimit": fetch_limit,
                "limited": True,
                "lastOkAt": int(time.time() * 1000),
                "lastCheckAt": int(time.time() * 1000),
            },
            "items": sorted_rows[:fetch_limit],
        }
    if successful:
        selected = min(successful, key=lambda result: safe_float(result.get("elapsed"), 999))
        with X_KOL_RSS_PREFERENCE_LOCK:
            X_KOL_RSS_PREFERRED_TEMPLATES[handle.lower()] = str(selected.get("template") or "")
        return {
            "source": {
                **source,
                "status": "ok",
                "provider": "rss",
                "feedUrl": selected.get("url") or "",
                "feedUrls": [result.get("url") for result in successful if result.get("url")],
                "itemsReturned": 0,
                "fetchLimit": fetch_limit,
                "limited": True,
                "lastOkAt": int(time.time() * 1000),
                "lastCheckAt": int(time.time() * 1000),
            },
            "items": [],
        }
    upstream_error = clean_feed_text(
        next((result.get("error") for result in results if result.get("error")), "No RSS mirror is currently ready"),
        240,
    )
    return {
        "source": {
            **source,
            "status": "error",
            "provider": "rss",
            "error": "上游暂时波动，正在自动换源",
            "upstreamError": upstream_error,
            "lastCheckAt": int(time.time() * 1000),
        },
        "items": [],
    }


def x_kol_fetch_rss_source(source: dict[str, Any]) -> dict[str, Any]:
    handle = source["handle"]
    templates = x_kol_rss_template_candidates(
        handle,
        x_rss_templates(),
        limit=X_KOL_RSS_MIRROR_ATTEMPTS,
    )

    results: list[dict[str, Any]] = []
    if templates:
        futures = [X_KOL_RSS_MIRROR_POOL.submit(x_kol_fetch_rss_template, source, template) for template in templates]
        for future in as_completed(futures):
            result = future.result()
            x_kol_record_rss_mirror_result(result)
            results.append(result)
    rss_payload = x_kol_rss_result_payload(source, results)
    if rss_payload.get("items"):
        return rss_payload
    fxtwitter_payload: dict[str, Any] = {}
    if x_kol_fxtwitter_fallback_enabled():
        fxtwitter_payload = x_kol_fetch_fxtwitter_timeline(source)
        fxtwitter_source = (
            fxtwitter_payload.get("source")
            if isinstance(fxtwitter_payload.get("source"), dict)
            else {}
        )
        if fxtwitter_source.get("status") == "ok":
            return fxtwitter_payload
    if not x_kol_public_timeline_fallback_enabled():
        return rss_payload
    public_payload = x_kol_fetch_public_timeline(source)
    public_source = public_payload.get("source") if isinstance(public_payload.get("source"), dict) else {}
    if public_source.get("status") == "ok":
        return public_payload
    if (rss_payload.get("source") or {}).get("status") == "ok":
        return rss_payload
    rss_source = rss_payload.get("source") if isinstance(rss_payload.get("source"), dict) else {}
    fx_source = fxtwitter_payload.get("source") if isinstance(fxtwitter_payload.get("source"), dict) else {}
    rss_source["fxtwitterFallbackError"] = fx_source.get("upstreamError") or fx_source.get("error") or ""
    rss_source["publicFallbackError"] = public_source.get("upstreamError") or public_source.get("error") or ""
    return rss_payload


def x_kol_fetch_priority_rss_source(source: dict[str, Any]) -> dict[str, Any]:
    handle = source["handle"]
    templates = x_kol_rss_template_candidates(
        handle,
        x_rss_templates(),
        limit=x_kol_priority_rss_mirrors(),
    )
    if not templates:
        return x_kol_rss_result_payload(source, [])

    results: list[dict[str, Any]] = []
    futures = [
        X_KOL_RSS_MIRROR_POOL.submit(
            x_kol_fetch_rss_template,
            source,
            template,
            timeout_seconds=x_kol_priority_rss_timeout_seconds(),
        )
        for template in templates
    ]
    try:
        for future in as_completed(futures):
            result = future.result()
            x_kol_record_rss_mirror_result(result)
            results.append(result)
            if result.get("ok"):
                return x_kol_rss_result_payload(source, [result])
    finally:
        for future in futures:
            future.cancel()
    rss_payload = x_kol_rss_result_payload(source, results)
    if rss_payload.get("items"):
        return rss_payload
    fxtwitter_payload: dict[str, Any] = {}
    if x_kol_fxtwitter_fallback_enabled():
        fxtwitter_payload = x_kol_fetch_fxtwitter_timeline(source)
        fxtwitter_source = (
            fxtwitter_payload.get("source")
            if isinstance(fxtwitter_payload.get("source"), dict)
            else {}
        )
        if fxtwitter_source.get("status") == "ok":
            return fxtwitter_payload
    if not x_kol_public_timeline_fallback_enabled():
        return rss_payload
    public_payload = x_kol_fetch_public_timeline(source)
    public_source = public_payload.get("source") if isinstance(public_payload.get("source"), dict) else {}
    if public_source.get("status") == "ok":
        return public_payload
    if (rss_payload.get("source") or {}).get("status") == "ok":
        return rss_payload
    rss_source = rss_payload.get("source") if isinstance(rss_payload.get("source"), dict) else {}
    fx_source = fxtwitter_payload.get("source") if isinstance(fxtwitter_payload.get("source"), dict) else {}
    rss_source["fxtwitterFallbackError"] = fx_source.get("upstreamError") or fx_source.get("error") or ""
    rss_source["publicFallbackError"] = public_source.get("upstreamError") or public_source.get("error") or ""
    return rss_payload


def x_kol_shared_person_activity(
    view_sources: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Project the shared person watcher cache into X tracking with no new request."""
    document = trench_person_activity_document()
    by_handle = {
        normalize_x_handle(source.get("handle")).casefold(): source
        for source in view_sources
        if normalize_x_handle(source.get("handle"))
    }
    health_rows = document.get("sourceHealth") if isinstance(document.get("sourceHealth"), dict) else {}
    states: list[dict[str, Any]] = []
    for health in health_rows.values():
        if not isinstance(health, dict):
            continue
        handle = normalize_x_handle(health.get("handle")).casefold()
        source = by_handle.get(handle)
        if not source:
            continue
        states.append({
            **source,
            **health,
            "id": source["id"],
            "handle": source["handle"],
            "displayName": source.get("displayName") or health.get("displayName") or source["handle"],
            "provider": health.get("provider") or "shared-person-watch",
            "sharedWatcher": True,
        })

    items: list[dict[str, Any]] = []
    for raw in document.get("recentPosts") if isinstance(document.get("recentPosts"), list) else []:
        if not isinstance(raw, dict):
            continue
        person_source = raw.get("_personSource") if isinstance(raw.get("_personSource"), dict) else {}
        handle = normalize_x_handle(raw.get("handle") or person_source.get("handle")).casefold()
        source = by_handle.get(handle)
        if not source:
            continue
        item = dict(raw)
        item.pop("_personSource", None)
        item.update({
            "sourceId": source["id"],
            "handle": source["handle"],
            "sourceName": source.get("displayName") or source["handle"],
            "provider": item.get("provider") or "shared-person-watch",
            "sharedWatcher": True,
        })
        items.append(item)
    return states, items


def x_kol_feed_payload(user: dict[str, Any] | None = None) -> dict[str, Any]:
    sources = load_x_kol_sources(user)
    enabled_sources = [source for source in sources if source.get("enabled") is not False]
    view_sources = x_kol_sources_for_view(user, manual_sources=sources)
    token = x_kol_token()
    paid_api_enabled = x_kol_official_api_enabled()
    paid_rest_poll_enabled = x_kol_official_rest_poll_enabled()
    items: list[dict[str, Any]] = []
    source_states: list[dict[str, Any]] = []

    def fetch_source(source: dict[str, Any]) -> dict[str, Any]:
        try:
            return (
                x_kol_fetch_api_source(source, token)
                if paid_rest_poll_enabled and x_kol_official_paid_source_allowed(source)
                else x_kol_fetch_rss_source(source)
            )
        except Exception as exc:
            return {
                "source": {
                    **source,
                    "status": "error",
                    "provider": "x-api" if paid_rest_poll_enabled else "rss",
                    "error": "上游暂时波动，正在自动重连",
                    "upstreamError": clean_feed_text(exc, 240),
                    "lastCheckAt": int(time.time() * 1000),
                },
                "items": [],
            }

    results_by_id: dict[str, dict[str, Any]] = {}
    if enabled_sources:
        futures = {X_KOL_RSS_SOURCE_POOL.submit(fetch_source, source): source for source in enabled_sources}
        for future in as_completed(futures):
            source = futures[future]
            results_by_id[str(source.get("id") or source.get("handle") or "")] = future.result()

    for source in enabled_sources:
        source_id = str(source.get("id") or source.get("handle") or "")
        result = results_by_id.get(source_id) or fetch_source(source)
        source_states.append(result["source"])
        items.extend(result["items"])

    # The system person roster is already polled by one serial, rate-limited
    # watcher. Reuse its cache here instead of fanning out another 200+ reads.
    person_states, person_items = x_kol_shared_person_activity(view_sources)
    state_map = {
        str(source.get("id") or source.get("handle") or ""): source
        for source in [*person_states, *source_states]
        if isinstance(source, dict)
    }
    source_states = list(state_map.values())
    items.extend(person_items)

    cutoff = int(time.time() * 1000) - X_KOL_RETENTION_MS
    unique_items: dict[str, dict[str, Any]] = {}
    for item in items:
        published_at = int(safe_float(item.get("publishedAt")) or 0)
        if published_at and published_at < cutoff:
            continue
        unique_items[item["id"]] = item
    sorted_items = sorted(unique_items.values(), key=lambda item: int(safe_float(item.get("publishedAt"))), reverse=True)[:240]
    return x_kol_overlay_official_stream_status({
        "ok": True,
        "sources": source_states,
        "items": sorted_items,
        "sourceCount": len(view_sources),
        "enabledCount": sum(1 for source in view_sources if source.get("enabled") is not False),
        "manualSourceCount": len(sources),
        "manualEnabledCount": len(enabled_sources),
        "systemSourceCount": len(view_sources) - len(sources),
        "provider": "x-api" if paid_rest_poll_enabled else "rss+shared-person-watch",
        "hasToken": bool(token),
        "paidApiEnabled": paid_api_enabled,
        "paidRestPollingEnabled": paid_rest_poll_enabled,
        "upstreamMode": "official-api" if paid_rest_poll_enabled else "rss-resilient",
        "updatedAt": int(time.time() * 1000),
    })


def decode_js_string(value: Any) -> str:
    raw = str(value or "")
    if not raw:
        return ""
    try:
        return html.unescape(json.loads(f'"{raw}"'))
    except Exception:
        try:
            return html.unescape(raw.encode("utf-8").decode("unicode_escape"))
        except Exception:
            return html.unescape(raw)


def extract_js_var(source: str, name: str) -> str:
    patterns = [
        rf"var\s+{re.escape(name)}\s*=\s*htmlDecode\(\s*(['\"])(.*?)(?<!\\)\1\s*\)",
        rf"var\s+{re.escape(name)}\s*=\s*(['\"])(.*?)(?<!\\)\1(?:\.html\(false\))?",
        rf"\b{re.escape(name)}\s*:\s*(['\"])(.*?)(?<!\\)\1",
    ]
    for pattern in patterns:
        match = re.search(pattern, source, flags=re.S)
        if match:
            return clean_feed_text(decode_js_string(match.group(2)), 1200)
    return ""


def soup_text(soup: BeautifulSoup, selector: str, limit: int = 160) -> str:
    node = soup.select_one(selector)
    return clean_feed_text(node.get_text(" ", strip=True), limit) if node else ""


def parse_wechat_timestamp(source: str) -> int:
    for name in ("ct", "publish_time", "createTime"):
        value = extract_js_var(source, name)
        if not value:
            continue
        if value.isdigit():
            number = int(value)
            return number * 1000 if number < 10_000_000_000 else number
        parsed = parse_feed_datetime(value)
        if parsed:
            return parsed
    meta_match = re.search(r'property=["\']article:published_time["\']\s+content=["\']([^"\']+)["\']', source)
    if meta_match:
        return parse_feed_datetime(meta_match.group(1))
    return 0


def normalize_wechat_article_url(value: Any) -> str:
    url = normalize_feed_url(value)
    parsed = urlparse(url)
    if parsed.netloc not in {"mp.weixin.qq.com", "mp.weixin.qq.com.cn"} and not parsed.netloc.endswith(".mp.weixin.qq.com"):
        raise ValueError("请输入微信公众号文章链接，域名应为 mp.weixin.qq.com")
    return url


def wechat_article_id(url: str) -> str:
    parsed = urlparse(url)
    if "/s/" in parsed.path:
        article_id = parsed.path.split("/s/", 1)[1].strip("/")
        if article_id:
            return article_id
    query = parse_qs(parsed.query)
    parts = [query.get(key, [""])[0] for key in ("__biz", "mid", "idx", "sn")]
    return stable_feed_id("wechat-article", url, *parts)


def parse_wechat_article(url: str) -> dict[str, Any]:
    article_url = normalize_wechat_article_url(url)
    headers = {
        **HEADERS,
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
        "Referer": "https://mp.weixin.qq.com/",
    }
    response = requests.get(article_url, headers=headers, timeout=18)
    response.encoding = "utf-8"
    source = response.text
    soup = BeautifulSoup(source, "html.parser")
    meta = {}
    for item in soup.find_all("meta"):
        key = item.get("property") or item.get("name")
        if key:
            meta[key] = item.get("content", "")

    article_author = (
        extract_js_var(source, "author")
        or soup_text(soup, "#js_author_name_text")
        or soup_text(soup, "#js_author_name")
        or clean_feed_text(meta.get("og:article:author") or meta.get("author"), 120)
    )
    mp_name = (
        soup_text(soup, "#js_name")
        or soup_text(soup, ".rich_media_meta_nickname a")
        or extract_js_var(source, "nickname")
        or extract_js_var(source, "nick_name")
        or article_author
        or "微信公众号"
    )
    title = (
        extract_js_var(source, "msg_title")
        or clean_feed_text(meta.get("og:title") or (soup.title.get_text(" ", strip=True) if soup.title else ""), 180)
    )
    summary = extract_js_var(source, "msg_desc") or clean_feed_text(meta.get("og:description") or meta.get("description"), 420)
    cover = extract_js_var(source, "msg_cdn_url") or clean_feed_text(meta.get("og:image"), 600)
    biz = extract_js_var(source, "biz") or parse_qs(urlparse(article_url).query).get("__biz", [""])[0]
    mp_id = stable_feed_id("wechat-mp", biz or mp_name or article_url)
    published = parse_wechat_timestamp(source)
    article_id = wechat_article_id(article_url)
    item = {
        "id": article_id,
        "title": title or article_url,
        "url": article_url,
        "publishedAt": published,
        "author": article_author or mp_name,
        "summary": summary,
        "image": cover,
    }
    return {
        "feed": {
            "id": mp_id,
            "title": mp_name,
            "siteUrl": article_url,
            "feedUrl": f"wechat-mp://{mp_id}",
            "description": summary,
            "cover": cover,
            "platform": "public-article",
            "seedUrl": article_url,
            "query": mp_name,
            "biz": biz,
        },
        "items": [item] if title or summary else [],
    }


def wechat_env_account() -> dict[str, Any]:
    account_id = os.getenv("WECHAT_ACCOUNT_ID") or os.getenv("WEWE_ACCOUNT_ID") or ""
    token = os.getenv("WECHAT_ACCOUNT_TOKEN") or os.getenv("WEWE_ACCOUNT_TOKEN") or ""
    if not account_id or not token:
        return {}
    return {
        "id": str(account_id).strip(),
        "token": str(token).strip(),
        "name": os.getenv("WECHAT_ACCOUNT_NAME") or "env account",
        "source": "env",
        "status": "active",
    }


def read_wechat_account_cache() -> dict[str, Any]:
    payload = read_json_cache(WECHAT_ACCOUNT_CACHE_PATH)
    accounts = payload.get("accounts")
    if not isinstance(accounts, list):
        payload["accounts"] = []
    return payload


def write_wechat_account_cache(payload: dict[str, Any]) -> None:
    payload["updatedAt"] = int(time.time())
    write_json_cache(WECHAT_ACCOUNT_CACHE_PATH, payload)


def wechat_source_alias_key(*values: Any) -> str:
    for value in values:
        text = clean_feed_text(value, 120).lower()
        text = re.sub(r"\s+", "", text)
        if text and not is_generic_wechat_title(text):
            return text
    return ""


def read_wechat_source_alias_cache() -> dict[str, Any]:
    payload = read_json_cache(WECHAT_SOURCE_ALIAS_CACHE_PATH)
    aliases = payload.get("aliases")
    if not isinstance(aliases, dict):
        payload["aliases"] = {}
    return payload


def write_wechat_source_alias_cache(payload: dict[str, Any]) -> None:
    payload["updatedAt"] = int(time.time())
    write_json_cache(WECHAT_SOURCE_ALIAS_CACHE_PATH, payload)


def public_wechat_source_alias(source: dict[str, Any]) -> dict[str, Any]:
    mp_id = clean_feed_text(source.get("mpId") or source.get("id"), 100)
    if not is_wechat_platform_mp_id(mp_id, "wewe-platform"):
        return {}
    return {
        "type": "wechat",
        "title": clean_feed_text(source.get("title") or source.get("name"), 120),
        "mpId": mp_id,
        "query": clean_feed_text(source.get("query") or source.get("title") or source.get("name"), 120),
        "seedUrl": clean_feed_text(source.get("seedUrl"), 900),
        "feedUrl": f"wechat-mp://{mp_id}",
        "cover": clean_feed_text(source.get("cover"), 900),
        "intro": clean_feed_text(source.get("intro") or source.get("description"), 240),
        "platform": "wewe-platform",
    }


def cache_wechat_source_alias(source: dict[str, Any]) -> None:
    alias = public_wechat_source_alias(source)
    if not alias:
        return
    keys = {
        wechat_source_alias_key(alias.get("title")),
        wechat_source_alias_key(alias.get("query")),
    }
    keys = {key for key in keys if key}
    if not keys:
        return
    payload = read_wechat_source_alias_cache()
    aliases = payload.setdefault("aliases", {})
    for key in keys:
        aliases[key] = {**aliases.get(key, {}), **alias, "updatedAt": int(time.time())}
    write_wechat_source_alias_cache(payload)


def cached_wechat_source_alias(*values: Any) -> dict[str, Any]:
    payload = read_wechat_source_alias_cache()
    aliases = payload.get("aliases") if isinstance(payload, dict) else {}
    if not isinstance(aliases, dict):
        return {}
    for value in values:
        key = wechat_source_alias_key(value)
        if not key:
            continue
        alias = aliases.get(key)
        if isinstance(alias, dict):
            public_alias = public_wechat_source_alias(alias)
            if public_alias:
                return public_alias
    return {}


def public_wechat_account(account: dict[str, Any]) -> dict[str, Any]:
    return {
        "id": clean_feed_text(account.get("id"), 80),
        "name": clean_feed_text(account.get("name") or account.get("username") or "微信读书账号", 120),
        "source": clean_feed_text(account.get("source") or "cache", 40),
        "status": clean_feed_text(account.get("status") or "active", 40),
        "lastOkAt": int(safe_float(account.get("lastOkAt"))),
        "lastCheckAt": int(safe_float(account.get("lastCheckAt"))),
        "lastError": clean_feed_text(account.get("lastError"), 180),
        "cooldownUntil": int(safe_float(account.get("cooldownUntil"))),
    }


def wechat_platform_accounts(include_unavailable: bool = False) -> list[dict[str, Any]]:
    now = int(time.time())
    payload = read_wechat_account_cache()
    accounts: list[dict[str, Any]] = []
    for raw in payload.get("accounts", []):
        if not isinstance(raw, dict):
            continue
        account_id = clean_feed_text(raw.get("id"), 80)
        token = str(raw.get("token") or "").strip()
        if not account_id or not token:
            continue
        status = clean_feed_text(raw.get("status") or "active", 40)
        cooldown_until = int(safe_float(raw.get("cooldownUntil")))
        if not include_unavailable and (status == "invalid" or cooldown_until > now):
            continue
        accounts.append(
            {
                **raw,
                "id": account_id,
                "token": token,
                "source": "cache",
                "status": status,
                "cooldownUntil": cooldown_until,
            }
        )

    env_account = wechat_env_account()
    if env_account:
        accounts.append(env_account)

    deduped: dict[str, dict[str, Any]] = {}
    for account in accounts:
        deduped.setdefault(account["id"], account)
    return list(deduped.values())


def wechat_platform_account() -> dict[str, Any]:
    accounts = wechat_platform_accounts()
    return accounts[0] if accounts else {}


def upsert_wechat_account(account: dict[str, Any]) -> dict[str, Any]:
    account_id = clean_feed_text(account.get("id") or account.get("vid"), 80)
    token = str(account.get("token") or "").strip()
    if not account_id or not token:
        raise ValueError("微信读书授权结果缺少账号 ID 或 token")
    payload = read_wechat_account_cache()
    accounts = [item for item in payload.get("accounts", []) if isinstance(item, dict)]
    now = int(time.time())
    saved = {
        "id": account_id,
        "token": token,
        "name": clean_feed_text(account.get("name") or account.get("username") or f"WeRead {account_id}", 120),
        "status": "active",
        "source": "cache",
        "createdAt": int(safe_float(account.get("createdAt"), now)),
        "updatedAt": now,
        "lastOkAt": now,
        "lastError": "",
        "cooldownUntil": 0,
    }
    replaced = False
    for index, item in enumerate(accounts):
        if clean_feed_text(item.get("id"), 80) == account_id:
            accounts[index] = {**item, **saved, "createdAt": int(safe_float(item.get("createdAt"), now))}
            replaced = True
            break
    if not replaced:
        accounts.insert(0, saved)
    payload["accounts"] = accounts[:8]
    write_wechat_account_cache(payload)
    return saved


def update_wechat_account_state(account: dict[str, Any], error: Exception | None = None) -> None:
    if account.get("source") != "cache":
        return
    payload = read_wechat_account_cache()
    accounts = [item for item in payload.get("accounts", []) if isinstance(item, dict)]
    account_id = clean_feed_text(account.get("id"), 80)
    now = int(time.time())
    changed = False
    auth_required_message = ""
    for item in accounts:
        if clean_feed_text(item.get("id"), 80) != account_id:
            continue
        item["updatedAt"] = now
        item["lastCheckAt"] = now
        if error is None:
            item["status"] = "active"
            item["lastOkAt"] = now
            item["lastError"] = ""
            item["cooldownUntil"] = 0
        else:
            message = clean_feed_text(str(error), 240)
            item["lastError"] = message
            if wechat_error_requires_auth(message):
                item["status"] = "invalid"
                auth_required_message = message
            elif "429" in message or "WeReadError429" in message:
                item["status"] = "cooldown"
                item["cooldownUntil"] = now + WECHAT_ACCOUNT_COOLDOWN_SECONDS
            else:
                item["status"] = clean_feed_text(item.get("status") or "active", 40)
        changed = True
        break
    if changed:
        payload["accounts"] = accounts
        write_wechat_account_cache(payload)
    if auth_required_message:
        try:
            notify_wechat_auth_required(auth_required_message)
        except Exception:
            pass


def wechat_platform_url() -> str:
    return (os.getenv("WECHAT_PLATFORM_URL") or os.getenv("WEWE_PLATFORM_URL") or "https://weread.111965.xyz").rstrip("/")


def wechat_platform_headers(account: dict[str, Any] | None = None) -> dict[str, str]:
    account = account or wechat_platform_account()
    if not account:
        raise ValueError("需要先完成微信读书授权，才能精确拉取公众号最新文章列表")
    return {
        **HEADERS,
        "xid": account["id"],
        "Authorization": f"Bearer {account['token']}",
        "Content-Type": "application/json",
    }


def wechat_platform_candidate_paths(path: str) -> list[str]:
    clean_path = "/" + str(path or "").lstrip("/")
    if clean_path.startswith("/api/platform/"):
        tail = clean_path.removeprefix("/api/platform/")
        return [clean_path, f"/api/v2/platform/{tail}"]
    if clean_path.startswith("/api/v2/platform/"):
        tail = clean_path.removeprefix("/api/v2/platform/")
        return [f"/api/platform/{tail}", clean_path]
    return [clean_path]


def wechat_platform_route_missing(error: Any) -> bool:
    text = str(error or "").lower()
    return "cannot get" in text or "cannot post" in text or "http 404" in text or "not found" in text


def wechat_platform_source_error(error: Any) -> bool:
    text = str(error or "").lower()
    return "no book found" in text


def wechat_platform_request(
    method: str,
    path: str,
    account: dict[str, Any] | None = None,
    *,
    mark_ok: bool = True,
    state_error: bool = True,
    **kwargs,
) -> Any:
    accounts = [account] if account else wechat_platform_accounts()
    accounts = [item for item in accounts if item]
    if not accounts:
        try:
            notify_wechat_auth_required("没有可用的微信公众号授权账号")
        except Exception:
            pass
        raise ValueError("需要先完成微信读书授权，才能精确拉取公众号最新文章列表")

    last_error: Exception | None = None
    extra_headers = kwargs.pop("headers", {}) or {}
    paths = wechat_platform_candidate_paths(path)
    for item in accounts:
        account_error: Exception | None = None
        for candidate_path in paths:
            request_kwargs = {**kwargs}
            request_kwargs.setdefault("timeout", 18)
            url = f"{wechat_platform_url()}{candidate_path}"
            try:
                response = requests.request(
                    method,
                    url,
                    headers={**wechat_platform_headers(item), **extra_headers},
                    **request_kwargs,
                )
                text = response.text[:500]
                if response.status_code >= 400:
                    try:
                        message = response.json().get("message") or text
                    except Exception:
                        message = text
                    raise RuntimeError(f"WeWe platform HTTP {response.status_code}: {message}")
                payload = response.json()
                if isinstance(payload, dict) and payload.get("message") and not payload.get("token"):
                    raise RuntimeError(str(payload.get("message")))
                if mark_ok:
                    update_wechat_account_state(item, None)
                return payload
            except Exception as exc:
                last_error = exc
                account_error = exc
                continue
        if state_error and account_error and not wechat_platform_route_missing(account_error) and not wechat_platform_source_error(account_error):
            update_wechat_account_state(item, account_error)
    if wechat_error_requires_auth(last_error):
        try:
            notify_wechat_auth_required(last_error)
        except Exception:
            pass
    raise last_error or ValueError("微信公众号平台接口请求失败")


def wechat_platform_resolve_article(url: str, account: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    payload = wechat_platform_request(
        "POST",
        "/api/platform/wxs2mp",
        account=account,
        json={"url": normalize_wechat_article_url(url)},
        mark_ok=False,
    )
    return payload if isinstance(payload, list) else []


def wechat_platform_articles(mp_id: str, page: int = 1, account: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    payload = wechat_platform_request(
        "GET",
        f"/api/platform/mps/{mp_id}/articles",
        account=account,
        params={"page": page},
    )
    return payload if isinstance(payload, list) else []


def wechat_platform_articles_pages(
    mp_id: str,
    page_limit: int = 1,
    cutoff_ms: int = 0,
    account: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    for page in range(1, max(1, page_limit) + 1):
        page_items = wechat_platform_articles(mp_id, page, account=account)
        if not page_items:
            break
        items.extend(page_items)
        if cutoff_ms:
            timestamps = [int(safe_float(item.get("publishTime")) * 1000) for item in page_items]
            known_timestamps = [value for value in timestamps if value > 0]
            if known_timestamps and max(known_timestamps) < cutoff_ms:
                break
    return items


def wechat_login_begin_payload() -> dict[str, Any]:
    response = requests.get(
        f"{wechat_platform_url()}/api/v2/login/platform",
        headers={**HEADERS, "Accept": "application/json"},
        timeout=18,
    )
    response.raise_for_status()
    payload = response.json()
    uuid = clean_feed_text(payload.get("uuid"), 80)
    if not uuid:
        raise ValueError("微信读书登录二维码创建失败")
    qr_data_url = wechat_qr_data_url(uuid)
    qr_image_path = wechat_qr_image_path(uuid, qr_data_url)
    return {
        "ok": True,
        "uuid": uuid,
        "scanUrl": clean_feed_text(payload.get("scanUrl"), 600),
        "qrUrl": f"https://open.weixin.qq.com/connect/qrcode/{uuid}",
        "qrDataUrl": qr_data_url,
        "qrImagePath": qr_image_path,
        "qrImageUrl": wechat_qr_image_public_url(uuid) if qr_image_path else "",
    }


def wechat_qr_data_url(uuid: str) -> str:
    if not uuid:
        return ""
    try:
        response = requests.get(
            f"https://open.weixin.qq.com/connect/qrcode/{quote(uuid, safe='')}",
            headers={**HEADERS, "Accept": "image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8"},
            timeout=12,
        )
        response.raise_for_status()
        content = response.content[:900_000]
        content_type = response.headers.get("Content-Type", "image/png").split(";", 1)[0] or "image/png"
        if not content:
            return ""
        return f"data:{content_type};base64,{base64.b64encode(content).decode('ascii')}"
    except Exception:
        return ""


def wechat_qr_image_path(uuid: str, data_url: str = "") -> str:
    uuid = re.sub(r"[^A-Za-z0-9_-]+", "", str(uuid or ""))[:80]
    if not uuid or not data_url:
        return ""
    match = re.match(r"^data:([^;,]+);base64,(.+)$", data_url, flags=re.I | re.S)
    if not match:
        return ""
    content_type = match.group(1).lower()
    raw = base64.b64decode(match.group(2))
    path = PERSIST_CACHE_DIR / f"wechat-auth-qr-{uuid}.png"
    try:
        cleanup_runtime_ephemeral_files(keep_qr_uuid=uuid)
        try:
            from PIL import Image

            image = Image.open(BytesIO(raw))
            image.save(path, format="PNG")
        except Exception:
            suffix = ".png"
            if "jpeg" in content_type or "jpg" in content_type:
                suffix = ".jpg"
            elif "gif" in content_type:
                suffix = ".gif"
            path = PERSIST_CACHE_DIR / f"wechat-auth-qr-{uuid}{suffix}"
            path.write_bytes(raw)
        return str(path)
    except Exception:
        return ""


def wechat_qr_image_file(uuid: str) -> Path | None:
    uuid = re.sub(r"[^A-Za-z0-9_-]+", "", str(uuid or ""))[:80]
    if not uuid:
        return None
    for suffix in (".png", ".jpg", ".jpeg", ".gif"):
        path = PERSIST_CACHE_DIR / f"wechat-auth-qr-{uuid}{suffix}"
        if path.exists() and path.is_file():
            return path
    return None


def runtime_public_base_url() -> str:
    configured = env_value("XINGYUN_PUBLIC_BASE_URL").rstrip("/")
    if configured:
        return configured
    host = env_value("XINGYUN_HOST", "127.0.0.1") or "127.0.0.1"
    if host in {"0.0.0.0", "::"}:
        host = "127.0.0.1"
    port = env_value("PORT") or env_value("XINGYUN_PORT") or "8765"
    return f"http://{host}:{port}"


def wechat_qr_image_public_url(uuid: str) -> str:
    uuid = re.sub(r"[^A-Za-z0-9_-]+", "", str(uuid or ""))[:80]
    if not uuid:
        return ""
    return f"{runtime_public_base_url()}/api/wechat-qr-image?uuid={quote(uuid, safe='')}"


def jwt_payload(token: Any) -> dict[str, Any]:
    parts = str(token or "").split(".")
    if len(parts) < 2:
        return {}
    try:
        body = parts[1] + "=" * (-len(parts[1]) % 4)
        payload = base64.urlsafe_b64decode(body.encode("ascii"))
        data = json.loads(payload.decode("utf-8", errors="ignore"))
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def iter_nested_dicts(value: Any, limit: int = 80) -> list[dict[str, Any]]:
    found: list[dict[str, Any]] = []
    queue: list[Any] = [value]
    while queue and len(found) < limit:
        current = queue.pop(0)
        if isinstance(current, dict):
            found.append(current)
            queue.extend(current.values())
        elif isinstance(current, list):
            queue.extend(current[:limit])
    return found


def wechat_login_account_from_result(result: Any) -> dict[str, Any]:
    containers = iter_nested_dicts(result)
    token_keys = ("token", "accessToken", "access_token", "jwt", "jwtToken", "Authorization", "authorization")
    id_keys = ("vid", "id", "userVid", "user_id", "userId", "xid", "unionid", "openid")
    name_keys = ("username", "name", "nickName", "nickname", "displayName")
    tokens: list[str] = []
    account_ids: list[str] = []
    names: list[str] = []

    for item in containers:
        for key in token_keys:
            value = item.get(key)
            if value:
                text = str(value).replace("Bearer ", "").strip()
                if text and text not in tokens:
                    tokens.append(text)
        for key in id_keys:
            value = clean_feed_text(item.get(key), 120)
            if value and value not in account_ids:
                account_ids.append(value)
        for key in name_keys:
            value = clean_feed_text(item.get(key), 120)
            if value and value not in names:
                names.append(value)

    for token in list(tokens):
        claims = jwt_payload(token)
        for key in ("vid", "id", "userVid", "user_id", "userId", "xid"):
            value = clean_feed_text(claims.get(key), 120)
            if value and value not in account_ids:
                account_ids.append(value)
        for key in ("name", "username", "nickname"):
            value = clean_feed_text(claims.get(key), 120)
            if value and value not in names:
                names.append(value)

    if tokens and account_ids:
        return {
            "id": account_ids[0],
            "token": tokens[0],
            "name": names[0] if names else f"WeRead {account_ids[0]}",
        }
    return {}


def wechat_existing_authorized_payload() -> dict[str, Any] | None:
    account = wechat_platform_account()
    if not account:
        return None
    return {"ok": True, "status": "authorized", "account": public_wechat_account(account), "fromCache": True}


def wechat_login_poll_payload(payload: dict[str, Any]) -> dict[str, Any]:
    uuid = clean_feed_text(payload.get("uuid"), 80)
    if not uuid:
        raise ValueError("缺少微信读书登录 uuid")
    try:
        response = requests.get(
            f"{wechat_platform_url()}/api/v2/login/platform/{uuid}",
            headers={**HEADERS, "Accept": "application/json"},
            timeout=35,
        )
        response.raise_for_status()
        result = response.json()
    except Exception as exc:
        cached = wechat_existing_authorized_payload()
        if cached:
            return {**cached, "message": "已检测到本机已有可用授权"}
        raise exc

    login_account = wechat_login_account_from_result(result)
    if login_account:
        account = upsert_wechat_account(login_account)
        return {"ok": True, "status": "authorized", "account": public_wechat_account(account)}
    cached = wechat_existing_authorized_payload()
    if cached:
        return {**cached, "message": "已检测到本机已有可用授权"}
    message = clean_feed_text(result.get("message") if isinstance(result, dict) else "", 160) or "waiting"
    return {
        "ok": True,
        "status": clean_feed_text(message, 80),
        "message": message,
    }


def wechat_error_requires_auth(error: Any) -> bool:
    text = str(error or "").lower()
    if "wereaderror400" in text and "no book found" not in text:
        return True
    return any(marker in text for marker in ("401", "invalid", "unauthorized", "token", "登录", "授权", "wereaderror401"))


def wechat_auth_probe_url() -> str:
    return env_value("WECHAT_AUTH_PROBE_ARTICLE_URL", "https://mp.weixin.qq.com/s/xn5lAIj5iDplUkbnwQSdEA")


def wechat_validate_account(account: dict[str, Any], *, force: bool = False) -> dict[str, Any]:
    now = int(time.time())
    status = clean_feed_text(account.get("status") or "active", 40)
    last_check_at = int(safe_float(account.get("lastCheckAt")))
    if not force and status != "invalid" and last_check_at and now - last_check_at < WECHAT_AUTH_VALIDATE_INTERVAL_SECONDS:
        return {**public_wechat_account(account), "valid": status != "invalid", "checked": False}

    try:
        payload = wechat_platform_resolve_article(wechat_auth_probe_url(), account=account)
        probe_mp_id = ""
        if isinstance(payload, list) and payload:
            probe_mp_id = clean_feed_text(payload[0].get("id") if isinstance(payload[0], dict) else "", 80)
        if probe_mp_id:
            wechat_platform_articles(probe_mp_id, 1, account=account)
        update_wechat_account_state(account, None)
        refreshed = public_wechat_account({**account, "status": "active", "lastOkAt": now, "lastCheckAt": now, "lastError": "", "cooldownUntil": 0})
        return {**refreshed, "valid": True, "checked": True}
    except Exception as exc:
        update_wechat_account_state(account, exc)
        requires_auth = wechat_error_requires_auth(exc)
        if requires_auth:
            try:
                notify_wechat_auth_required(exc)
            except Exception:
                pass
        refreshed = public_wechat_account(
            {
                **account,
                "status": "invalid" if requires_auth else status,
                "lastCheckAt": now,
                "lastError": str(exc),
            }
        )
        return {**refreshed, "valid": not requires_auth and status != "invalid", "checked": True}


def wechat_auth_poll_worker(uuid: str) -> None:
    try:
        for _ in range(300):
            time.sleep(2)
            try:
                payload = wechat_login_poll_payload({"uuid": uuid})
            except Exception:
                continue
            if payload.get("status") == "authorized":
                account = payload.get("account") if isinstance(payload.get("account"), dict) else {}
                try:
                    rss_refresh_all_payload({"fullSync": False, "workers": 2}, admin_user())
                except Exception as exc:
                    print(f"WeChat auth refresh failed: {exc}", file=sys.stderr)
                launch_desktop_alert(
                    {
                        "key": f"wechat-auth-ok:{account.get('id') or uuid}",
                        "kind": "公众号授权",
                        "source": "微信公众号订阅",
                        "sourceLabel": "微",
                        "title": f"授权完成：{account.get('name') or '微信读书账号'}",
                        "body": "公众号订阅会在下一轮自动更新时继续拉取最新文章。",
                        "url": "http://127.0.0.1:8765/rss.html",
                        "priority": "已恢复",
                    }
                )
                return
    finally:
        with WECHAT_AUTH_ALERT_LOCK:
            WECHAT_AUTH_POLLING_UUIDS.discard(uuid)


def start_wechat_auth_poll(uuid: str) -> None:
    if not uuid:
        return
    with WECHAT_AUTH_ALERT_LOCK:
        if uuid in WECHAT_AUTH_POLLING_UUIDS:
            return
        WECHAT_AUTH_POLLING_UUIDS.add(uuid)
    threading.Thread(target=wechat_auth_poll_worker, args=(uuid,), daemon=True).start()


def notify_wechat_auth_required(reason: Any = "", *, force: bool = False, slot_label: str = "") -> dict[str, Any]:
    global WECHAT_AUTH_ALERT_LAST_AT
    if env_flag("XINGYUN_DISABLE_WECHAT_AUTH_ALERTS"):
        return {
            "ok": True,
            "skipped": True,
            "suppressed": True,
            "reason": "微信公众号授权弹窗已关闭",
        }
    now = time.time()
    with WECHAT_AUTH_ALERT_LOCK:
        if not force and now - WECHAT_AUTH_ALERT_LAST_AT < WECHAT_AUTH_ALERT_COOLDOWN_SECONDS:
            return {"ok": True, "cooldown": True}
        WECHAT_AUTH_ALERT_LAST_AT = now

    try:
        login_payload = wechat_login_begin_payload()
    except Exception:
        with WECHAT_AUTH_ALERT_LOCK:
            WECHAT_AUTH_ALERT_LAST_AT = 0.0
        raise
    uuid = clean_feed_text(login_payload.get("uuid"), 80)
    qr_url = clean_feed_text(login_payload.get("qrUrl"), 600)
    qr_image_path = clean_feed_text(login_payload.get("qrImagePath"), 600) or wechat_qr_image_path(
        uuid,
        clean_feed_text(login_payload.get("qrDataUrl"), 1_000_000),
    )
    qr_image_url = clean_feed_text(login_payload.get("qrImageUrl"), 600) or wechat_qr_image_public_url(uuid) or qr_url
    start_wechat_auth_poll(uuid)
    message = clean_feed_text(reason, 120) or "授权已失效或缺少可用账号"
    slot_label = clean_feed_text(slot_label, 24)
    title = "微信公众号授权需要更新"
    if slot_label:
        title = f"{title}（{slot_label}）"
    alert_key = f"wechat-auth-required:{uuid if force else int(now // WECHAT_AUTH_ALERT_COOLDOWN_SECONDS)}"
    return launch_desktop_alert(
        {
            "key": alert_key,
            "kind": "公众号授权",
            "source": "微信公众号订阅",
            "sourceLabel": "微",
            "title": title,
            "body": f"{message}。请用微信扫码，成功后会自动恢复订阅更新。",
            "url": "http://127.0.0.1:8765/rss.html",
            "imageUrl": qr_image_url,
            "imagePath": qr_image_path,
            "priority": "扫码授权",
        }
    )


def wechat_account_status_payload(*, force_validate: bool = False) -> dict[str, Any]:
    raw_accounts = wechat_platform_accounts(include_unavailable=True)
    validated: list[dict[str, Any]] = []
    for account in raw_accounts:
        if account.get("token"):
            validated.append(wechat_validate_account(account, force=force_validate))
        else:
            validated.append({**public_wechat_account(account), "valid": False, "checked": False})
    accounts = validated
    cached_accounts = [item for item in accounts if item.get("source") == "cache"]
    active = [item for item in accounts if item.get("valid") and item.get("status") == "active"]
    invalid = [item for item in accounts if item.get("status") == "invalid" or item.get("valid") is False]
    needs_auth = bool(cached_accounts and (not active or invalid))
    if needs_auth:
        try:
            notify_wechat_auth_required("公众号授权已失效或不可用")
        except Exception:
            pass
    return {
        "ok": True,
        "authorized": bool(active),
        "needsAuth": needs_auth,
        "activeCount": len(active),
        "invalidCount": len(invalid),
        "accounts": accounts,
        "platformUrl": wechat_platform_url(),
    }


def source_from_wechat_mp_info(info: dict[str, Any], seed_url: str = "") -> dict[str, Any]:
    mp_id = clean_feed_text(info.get("id"), 80) or stable_feed_id("wechat-mp", info.get("name"), seed_url)
    title = clean_feed_text(info.get("name") or info.get("mpName") or "微信公众号", 120)
    return {
        "type": "wechat",
        "title": title,
        "mpId": mp_id,
        "query": title,
        "seedUrl": seed_url,
        "feedUrl": f"wechat-mp://{mp_id}",
        "cover": clean_feed_text(info.get("cover") or info.get("mpCover"), 600),
        "intro": clean_feed_text(info.get("intro") or info.get("mpIntro"), 300),
        "updateTime": (safe_float(info.get("updateTime")) * 1000) if info.get("updateTime") else 0,
        "platform": "wewe-platform",
    }


def parse_sogou_time(value: str) -> int:
    text = clean_feed_text(value, 80)
    if not text:
        return 0
    now = int(time.time() * 1000)
    number_match = re.search(r"(\d+)", text)
    number = int(number_match.group(1)) if number_match else 0
    if "分钟前" in text:
        return now - number * 60_000
    if "小时前" in text:
        return now - number * 3_600_000
    if "天前" in text:
        return now - number * 86_400_000
    parsed = parse_feed_datetime(text)
    if parsed:
        return parsed
    date_match = re.search(r"(\d{4})[-/年](\d{1,2})[-/月](\d{1,2})", text)
    if date_match:
        y, m, d = [int(item) for item in date_match.groups()]
        return int(datetime(y, m, d).timestamp() * 1000)
    return 0


def fetch_sogou_wechat_articles(query: str, limit: int = 20) -> list[dict[str, Any]]:
    keyword = clean_feed_text(query, 80)
    if not keyword:
        return []
    url = f"https://weixin.sogou.com/weixin?type=2&ie=utf8&query={quote(keyword)}"
    headers = {
        **HEADERS,
        "Referer": "https://weixin.sogou.com/",
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
    }
    response = requests.get(url, headers=headers, timeout=18)
    response.encoding = response.apparent_encoding or "utf-8"
    source = response.text
    if "请输入验证码" in source or "antispider" in source.lower():
        raise ValueError("搜狗微信触发验证码，建议改用公众号文章链接并配置 WeWe 平台账号")
    soup = BeautifulSoup(source, "html.parser")
    rows = soup.select(".news-list li")
    items = []
    for row in rows[:limit]:
        link_node = row.select_one(".txt-box h3 a") or row.select_one("h3 a")
        if not link_node:
            continue
        title = clean_feed_text(link_node.get_text(" ", strip=True), 180)
        href = link_node.get("href") or ""
        if href.startswith("/"):
            href = urljoin("https://weixin.sogou.com", href)
        summary = clean_feed_text((row.select_one(".txt-info") or row).get_text(" ", strip=True), 420)
        author = clean_feed_text((row.select_one(".s-p a") or row.select_one(".account")).get_text(" ", strip=True) if row.select_one(".s-p a") or row.select_one(".account") else keyword, 80)
        if author and keyword and keyword not in author and author not in keyword:
            continue
        time_node = row.select_one(".s2") or row.select_one(".time")
        published = parse_sogou_time(time_node.get_text(" ", strip=True) if time_node else "")
        image = ""
        image_node = row.select_one("img")
        if image_node:
            image = image_node.get("src") or image_node.get("data-src") or ""
        items.append(
            {
                "id": stable_feed_id("sogou-wechat", href, title),
                "title": title or href,
                "url": href,
                "publishedAt": published,
                "author": author,
                "summary": summary,
                "image": urljoin("https://weixin.sogou.com", image) if image else "",
            }
        )
    return items


def resolve_wechat_mp_payload(payload: dict[str, Any]) -> dict[str, Any]:
    raw = clean_feed_text(payload.get("input") or payload.get("url") or payload.get("query") or payload.get("raw"), 600)
    title_override = clean_feed_text(payload.get("title"), 120)
    if not raw:
        raise ValueError("请填写公众号名称，或粘贴公众号任意一篇文章链接")
    if raw.startswith("mp.weixin.qq.com/"):
        raw = f"https://{raw}"
    if raw.startswith("http"):
        try:
            matches = wechat_platform_resolve_article(raw) if wechat_platform_account() else []
            if matches:
                source = source_from_wechat_mp_info(matches[0], raw)
                cache_wechat_source_alias(source)
            else:
                parsed = parse_wechat_article(raw)
                source = {
                    "type": "wechat",
                    "title": parsed["feed"]["title"],
                    "mpId": parsed["feed"]["id"],
                    "query": parsed["feed"].get("query") or parsed["feed"]["title"],
                    "seedUrl": raw,
                    "feedUrl": parsed["feed"]["feedUrl"],
                    "cover": parsed["feed"].get("cover", ""),
                    "intro": parsed["feed"].get("description", ""),
                    "platform": parsed["feed"].get("platform", "public-article"),
                    "biz": parsed["feed"].get("biz", ""),
                }
        except Exception:
            parsed = parse_wechat_article(raw)
            source = {
                "type": "wechat",
                "title": parsed["feed"]["title"],
                "mpId": parsed["feed"]["id"],
                "query": parsed["feed"].get("query") or parsed["feed"]["title"],
                "seedUrl": raw,
                "feedUrl": parsed["feed"]["feedUrl"],
                "cover": parsed["feed"].get("cover", ""),
                "intro": parsed["feed"].get("description", ""),
                "platform": parsed["feed"].get("platform", "public-article"),
                "biz": parsed["feed"].get("biz", ""),
            }
    else:
        raise ValueError("公众号精确订阅需要粘贴该公众号任意一篇文章链接；不再使用搜索结果作为公众号列表")
    if title_override:
        source["title"] = title_override
    return {"ok": True, "source": source}


def wechat_mp_fetch_payload(payload: dict[str, Any]) -> dict[str, Any]:
    source = payload.get("source") if isinstance(payload.get("source"), dict) else payload
    mp_id = clean_feed_text(source.get("mpId"), 100)
    seed_url = clean_feed_text(source.get("seedUrl"), 600)
    query = clean_feed_text(source.get("query") or source.get("title"), 120)
    title = clean_feed_text(source.get("title") or query or "微信公众号", 120)
    platform = source.get("platform") or ""
    if is_generic_wechat_title(title) and query and not is_generic_wechat_title(query):
        title = query
    if mp_id and not is_wechat_platform_mp_id(mp_id, platform):
        mp_id = ""
    if not mp_id:
        cached_source = cached_wechat_source_alias(title, query)
        if cached_source:
            mp_id = cached_source.get("mpId") or ""
            title = cached_source.get("title") or title
            query = cached_source.get("query") or query
            seed_url = seed_url or cached_source.get("seedUrl") or ""
            source = {**source, **cached_source}
            platform = "wewe-platform"

    items: list[dict[str, Any]] = []
    warning = ""
    notice = ""
    platform_items_count = 0
    has_wechat_account = bool(wechat_platform_account())
    cutoff_ms = int(time.time() * 1000) - RSS_RETENTION_MS
    allow_history_fallback = payload.get("allowHistoryFallback") is not False
    if not has_wechat_account:
        try:
            notify_wechat_auth_required("当前没有可用的微信公众号授权账号")
        except Exception:
            pass

    if seed_url and has_wechat_account and platform != "wewe-platform":
        resolve_errors: list[str] = []
        candidate_urls = [seed_url]
        for candidate in wechat_seed_candidates_from_alert_history(title):
            if candidate not in candidate_urls:
                candidate_urls.append(candidate)
        for candidate_url in candidate_urls[:12]:
            try:
                matches = wechat_platform_resolve_article(candidate_url)
                if matches:
                    platform_source = source_from_wechat_mp_info(matches[0], candidate_url)
                    cache_wechat_source_alias(platform_source)
                    mp_id = platform_source.get("mpId") or mp_id
                    title = platform_source.get("title") or title
                    query = platform_source.get("query") or query
                    seed_url = candidate_url
                    source = {**source, **platform_source}
                    platform = "wewe-platform"
                    warning = ""
                    break
            except Exception as exc:
                resolve_errors.append(str(exc))
        if platform != "wewe-platform" and resolve_errors:
            warning = f"公众号账号接口解析失败：{resolve_errors[-1]}"

    if mp_id and has_wechat_account and not platform.startswith("sogou"):
        try:
            page_limit = (
                WECHAT_PLATFORM_BACKFILL_PAGE_LIMIT
                if payload.get("backfill") or payload.get("fullSync")
                else WECHAT_PLATFORM_AUTO_PAGE_LIMIT
            )
            platform_items = wechat_platform_articles_pages(mp_id, page_limit=page_limit, cutoff_ms=cutoff_ms)
            platform_items_count = len(platform_items)
            for item in platform_items:
                article_id = clean_feed_text(item.get("id"), 120)
                items.append(
                    {
                        "id": article_id or stable_feed_id("wechat-platform", item.get("title")),
                        "title": clean_feed_text(item.get("title"), 180),
                        "url": f"https://mp.weixin.qq.com/s/{article_id}" if article_id else "",
                        "publishedAt": int(safe_float(item.get("publishTime")) * 1000),
                        "author": title,
                        "summary": "",
                        "image": clean_feed_text(item.get("picUrl"), 600),
                    }
                )
        except Exception as exc:
            warning = f"公众号最新列表拉取失败：{exc}"
            if wechat_error_requires_auth(exc):
                try:
                    notify_wechat_auth_required(exc)
                except Exception:
                    pass

    if seed_url:
        try:
            parsed = parse_wechat_article(seed_url)
            parsed_title = clean_feed_text(parsed["feed"].get("title"), 120)
            if parsed_title and not is_generic_wechat_title(parsed_title):
                title = parsed_title
            items.extend(parsed["items"])
            if not query:
                parsed_query = clean_feed_text(parsed["feed"].get("query") or parsed_title, 120)
                if parsed_query and not is_generic_wechat_title(parsed_query):
                    query = parsed_query
        except Exception:
            pass

    used_history_items = False
    if allow_history_fallback and not items:
        history_items = wechat_history_items_for_source(title or query, cutoff_ms=cutoff_ms)
        if history_items:
            items.extend(history_items)
            used_history_items = True
            warning = ""
            notice = "已使用本地历史内容；重新粘贴该公众号任意一篇原文链接后可恢复实时更新。"

    if not platform_items_count and not warning and not used_history_items:
        if has_wechat_account and not mp_id:
            notice = "该公众号源缺少真实公众号 ID，历史文章链接无法解析；请重新粘贴该公众号任意文章链接修复订阅"
        elif has_wechat_account:
            notice = "公众号接口本轮没有返回列表，已保留本地历史内容"
        else:
            notice = "微信公众号授权已失效或不可用，扫码授权后才能精确拉取公众号最新列表"

    deduped: dict[str, dict[str, Any]] = {}
    for item in items:
        key = clean_feed_text(item.get("id") or item.get("url") or item.get("title"), 160)
        if key and key not in deduped:
            deduped[key] = item
    items = sorted(deduped.values(), key=lambda item: item.get("publishedAt") or 0, reverse=True)
    items = recent_feed_items(items, cutoff_ms)
    items, skipped_existing = incremental_items(items, payload)
    feed_id = mp_id or stable_feed_id("wechat-mp", title, seed_url, query)
    return {
        "ok": True,
        "feed": {
            "id": feed_id,
            "title": title,
            "siteUrl": seed_url,
            "feedUrl": f"wechat-mp://{feed_id}",
            "description": clean_feed_text(source.get("intro"), 220),
            "cover": clean_feed_text(source.get("cover"), 600),
            "platform": platform or "public-article",
        },
        "items": [
            {**item, "sourceTitle": title}
            for item in items
            if item.get("title") or item.get("url")
        ],
        "skippedExisting": skipped_existing,
        "incremental": bool(payload.get("knownIds") or payload.get("since")),
        "warning": warning,
        "notice": notice,
        "platformItems": platform_items_count,
        "fetchedAt": int(time.time() * 1000),
    }


def safe_float(value: Any, default: float = 0.0) -> float:
    try:
        if value is None or value == "":
            return default
        return float(value)
    except (TypeError, ValueError):
        return default


def pct(value: float) -> str:
    sign = "+" if value > 0 else ""
    return f"{sign}{value:.2f}%"


def signed(value: float) -> str:
    sign = "+" if value > 0 else ""
    return f"{sign}{value:g}"


def money_usd(value: float) -> str:
    value = safe_float(value)
    abs_value = abs(value)
    if abs_value >= 1_000_000_000:
        return f"${value / 1_000_000_000:.2f}B"
    if abs_value >= 1_000_000:
        return f"${value / 1_000_000:.2f}M"
    if abs_value >= 1_000:
        return f"${value / 1_000:.2f}K"
    return f"${value:.0f}"


def money_cny(value: float) -> str:
    value = safe_float(value)
    abs_value = abs(value)
    if abs_value >= 100_000_000:
        return f"¥{value / 100_000_000:.2f}亿"
    if abs_value >= 10_000:
        return f"¥{value / 10_000:.2f}万"
    return f"¥{value:.0f}"


def compact_number(value: float) -> str:
    value = safe_float(value)
    abs_value = abs(value)
    if abs_value >= 1_000_000_000:
        return f"{value / 1_000_000_000:.2f}B"
    if abs_value >= 1_000_000:
        return f"{value / 1_000_000:.2f}M"
    if abs_value >= 1_000:
        return f"{value / 1_000:.2f}K"
    return f"{value:g}"


